### Example: Minimal API endpoint extension

One extension method per feature area on `RouteGroupBuilder`. No individual routes in `Program.cs`.  
Canonical: `find_symbol("WeatherEndpoints")`

```csharp
public static class WeatherEndpoints
{
    public static string BasePath = "weather";

    public static IEndpointRouteBuilder MapWeatherEndpoints(this IEndpointRouteBuilder endpoints)
    {
        endpoints.MapGet($"{BasePath}/forecast", async (HttpContext context, IApiService apiService) =>
        {
            var query      = new GetWeatherQuery();
            var validation = new Validation<GetWeatherQuery>().Validate(query);
            if (!validation.IsValid) return validation.Result;
            var result = await apiService.RequestAsync(query).ConfigureAwait(false);
            return Results.Ok(result);
        })
        .Produces<List<GetWeatherQueryResult>>()
        .WithName("GetWeatherForecast")
        .WithSummary("Returns weather forecast entries for the current day")
        .WithTags("Weather")
        .WithOpenApi();

        endpoints.MapPost($"{BasePath}/forecast", async (SaveWeatherForecastCommand command, IApiService apiService) =>
        {
            // Command binds directly from the request body (implements IWeatherForecast
            // and carries [Required]/[Range] attributes).
            var validation = new Validation<SaveWeatherForecastCommand>().Validate(command);
            if (!validation.IsValid) return validation.Result;
            await apiService.SendAsync(command).ConfigureAwait(false);
            return Results.NoContent();
        })
        .Produces(StatusCodes.Status204NoContent)
        .ProducesValidationProblem()
        .WithName("SaveWeatherForecast")
        .WithSummary("Persists a single weather forecast entry")
        .WithTags("Weather")
        .WithOpenApi();

        return endpoints;
    }
}
```

