### Example: Service

Interface + implementation in `Services/Services/{Name}/`. Service maps Domain ↔ Repository entity — the repository never sees Domain types.  
Canonical: `find_symbol("WeatherService")`

```csharp
public interface IWeatherService
{
    Task<List<IWeatherForecast>> GetWeatherAsync();
    Task SaveWeatherAsync(IWeatherForecast forecast);
}

public class WeatherService : IWeatherService
{
    private readonly IWeatherRepository _weatherRepository;

    public WeatherService(IWeatherRepository weatherRepository)
    {
        _weatherRepository = weatherRepository;
    }

    public async Task<List<IWeatherForecast>> GetWeatherAsync()
    {
        var entities = await _weatherRepository.GetWeatherAsync().ConfigureAwait(false);
        return entities.Select(e => new WeatherForecast
        {
            EndDate      = e.EndTime,
            StartDate    = e.StartTime,
            Summary      = e.Condition,
            TemperatureC = e.TemperatureC,
        } as IWeatherForecast).ToList();
    }

    public Task SaveWeatherAsync(IWeatherForecast forecast)
    {
        var entity = new WeatherEntity
        {
            StartTime    = forecast.StartDate,
            EndTime      = forecast.EndDate,
            TemperatureC = forecast.TemperatureC,
            Condition    = forecast.Summary ?? string.Empty,
        };
        return _weatherRepository.SaveAsync(entity);
    }
}
```

