### Minimal examples (adapted shapes — not copy-pasted production payloads)

**API smoke with `cy.request` + fixture + arrange/act/assert:**

```typescript
import smsPayload from '@root/fixtures/dev/sms.json';
import { sendSmsRequest } from '@root/common/context';

describe('SMS API', () => {
  it('accepts a send request', () => {
    // arrange
    const request = sendSmsRequest(smsPayload);
    // act
    cy.request(request).then(({ body }) => {
      // assert
      expect(body.isSuccess).to.eq(true);
    });
  });
});
```

**Request builder (same idea as messaging `context.ts`):**

```typescript
export const getWidget = (id: number) => ({
  method: 'GET' as const,
  url: `${Cypress.config('baseUrl')}/api/v1/widgets/${id}`,
  headers: { Authorization: `Bearer ${Cypress.env('access_token')}` },
});
```

**Alias to pass state between helpers:**

```typescript
cy.wrap({ id: 42, token: 'abc' }).as('ctx');
cy.get<{ id: number; token: string }>('@ctx').then((ctx) => {
  cy.request(getWidget(ctx.id)).its('status').should('eq', 200);
});
```

