### Example: Domain client hook

Canonical: `find_symbol("useWeatherClient")` (`src/frontend/src/clients/useWeatherClient.ts`)

```tsx
import { useRef, useEffect } from 'react';
import { useUserContext } from '@root/providers/user_context';
import { useApplicationContext } from '@root/providers/application_context';
import { configureClient } from './axiosClient';
import { useAxiosClient } from './useAxiosClient';
import { miniStore, useMiniStore, type IMiniStore } from '@root/components/shared/miniStore.ts';
import { components } from '@root/api_module/types';

export type GetWeatherQueryResult = components['schemas']['GetWeatherQueryResult'];

// Expose miniStore handles — each consumer subscribes only to what it reads.
export interface IUseWeatherClientResult {
  $initialized: IMiniStore<boolean>;
  $isLoading: IMiniStore<boolean>;
  $error: IMiniStore<string>;
  $weather: IMiniStore<GetWeatherQueryResult[]>;
  getWeather: () => Promise<GetWeatherQueryResult[]>;
}

export const useWeatherClient = (): IUseWeatherClientResult => {
  // Read upstream context via its handles.
  const { $accessToken } = useUserContext();
  const accessToken = useMiniStore($accessToken);
  const { $config } = useApplicationContext();
  const config = useMiniStore($config);
  const clientRef = useRef(null);
  // useAxiosClient owns $isLoading / $error; pass the handles straight through.
  const { $isLoading, $error, request } = useAxiosClient(clientRef.current);

  // Own the cache + readiness as stores (created once so the handle stays stable).
  const initializedRef = useRef<boolean>(false);
  const weatherRef = useRef<GetWeatherQueryResult[]>(null);
  const $initialized = useRef(miniStore.create(initializedRef)).current;
  const $weather = useRef(miniStore.create(weatherRef)).current;

  useEffect(() => {
    if (accessToken && clientRef.current == null) {
      clientRef.current = configureClient({ accessToken, apiKey: config.apiKey, baseUrl: '/api', correlationId: null, cloudTraceContext: null });
      $initialized.set(true);
    }
  }, [accessToken, clientRef.current]);

  const getWeather = (): Promise<GetWeatherQueryResult[]> => {
    if (clientRef.current && !$isLoading.get()) {   // read a handle imperatively with .get()
      return request({ url: '/v1/weather/forecast', method: 'get' }).then((data) => {
        $weather.set(data as GetWeatherQueryResult[]);
        return data as GetWeatherQueryResult[];
      });
    }
    return Promise.resolve($weather.get());
  };

  return { $initialized, $isLoading, $error, $weather, getWeather };
};
```

A component consumes it by subscribing to the handles it needs:

```tsx
const { weatherClient } = useAxiosContext();
const { $initialized, $isLoading, $weather, getWeather } = weatherClient;
const initialized = useMiniStore($initialized);
const isLoading   = useMiniStore($isLoading);
const weather     = useMiniStore($weather);
```

Registering a new client: add it to `IAxiosContextType` and instantiate it in `AxiosContextProvider`.  
Canonical: `find_symbol("IAxiosContextType")`, `find_symbol("AxiosContextProvider")`

```tsx
// In axios_context.tsx — add the new client alongside weatherClient
interface IAxiosContextType {
  weatherClient: ReturnType<typeof useWeatherClient>;
  // myNewClient: ReturnType<typeof useMyNewClient>;
}

export const AxiosContextProvider = ({ value, children }): React.ReactElement => {
  const initialValue = { ...DEFAULT_VALUE, ...value };
  const weatherClient = useWeatherClient();
  // const myNewClient = useMyNewClient();
  return (
    <AxiosContext.Provider value={{ ...initialValue, weatherClient }}>
      {children}
    </AxiosContext.Provider>
  );
};
```

