## Host wiring — Program.cs

The `#region caching` block in `Program.cs` wires the Redis infrastructure. This is already in place; no changes are needed when adding a new provider.

```csharp
#region caching
var endpoints    = configuration.GetValue<string>("redis:EndPoints")?.Split(';') ?? Array.Empty<string>();
var isEnabled    = bool.TryParse(configuration.GetValue<string>("redis:Enabled"),        out var enabled);
var isSsl        = bool.TryParse(configuration.GetValue<string>("redis:Ssl"),            out var ssl);
var certStr      = configuration.GetValue<string>("redis:CACertificate");
var isConnTimeout = int.TryParse(configuration.GetValue<string>("redis:ConnectTimeout"), out var connectTimeout);
var isAsyncTo    = int.TryParse(configuration.GetValue<string>("redis:AsyncTimeout"),    out var asyncTimeout);
var isSyncTo     = int.TryParse(configuration.GetValue<string>("redis:SyncTimeout"),     out var syncTimeout);

// CA certificate — only decoded when Ssl=true and a cert value is present.
// Locally both flags are false so this block is a no-op.
// In containers the cert is injected at deploy time (secret / env var mapped to
// redis:CACertificate) — never committed to appsettings.json.
X509Certificate2 cert = null;
try
{
    if (!string.IsNullOrEmpty(certStr) && ssl && enabled)
    {
        byte[] certBytes = Convert.FromBase64String(certStr);
        cert = new X509Certificate2(certBytes);
    }
}
catch (Exception ex) { Console.Write(ex.Message); }

// IRxoRedisCache singleton — injected into every CacheProviderBase subclass
builder.Services.AddSingleton<IRxoRedisCache, RxoRedisCache>();

// RxoRedisConfig factory — reads useCache header/querystring to allow per-request bypass
builder.Services.AddSingleton(c =>
{
    var httpContext = c.GetRequiredService<IHttpContextAccessor>().HttpContext;
    var isDisabled  = httpContext.Request.Query["useCache"] == "false"
                   || httpContext.Request.Headers["useCache"] == "false";
    return new RxoRedisConfig
    {
        Environment    = environment,
        Enabled        = isEnabled && enabled && !isDisabled,
        Ssl            = isSsl && ssl,
        Endpoints      = endpoints,
        CACertificate  = cert,
        AsyncTimeout   = isAsyncTo    ? asyncTimeout   : 350,
        ConnectTimeout = isConnTimeout ? connectTimeout : 5000,
        SyncTimeout    = isSyncTo     ? syncTimeout    : 350,
    };
});
#endregion
```

