using Xunit;

namespace Rxo.Platform.Api.Sandbox.Client.Tests
{

public class SandboxApiClientTests
{
    private readonly Mock<HttpMessageHandler> _httpHandler;

    public SandboxApiClientTests()
    {
        _httpHandler = new Mock<HttpMessageHandler>();
    }

    private SandboxApiClient GetClient()
    {
        var httpClient = new HttpClient(_httpHandler.Object)
        {
            BaseAddress = new Uri("https://api.example.com/"),
        };
        return new SandboxApiClient(httpClient);
    }

    private void SetupResponse(HttpStatusCode statusCode, string? body = null)
    {
        _httpHandler.Protected()
            .Setup<Task<HttpResponseMessage>>(
                "SendAsync",
                ItExpr.IsAny<HttpRequestMessage>(),
                ItExpr.IsAny<CancellationToken>())
            .ReturnsAsync(new HttpResponseMessage
            {
                StatusCode = statusCode,
                Content = body is null
                    ? new StringContent(string.Empty)
                    : new StringContent(body, Encoding.UTF8, "application/json"),
            });
    }

    [Fact]
    public async Task GetWeatherForecastAsync_DeserializesStreamedResponse()
    {
        // arrange
        var payload = JsonConvert.SerializeObject(new[]
        {
            new WeatherForecast
            {
                StartDate = new DateTime(2026, 5, 14, 9, 0, 0, DateTimeKind.Utc),
                EndDate = new DateTime(2026, 5, 14, 10, 0, 0, DateTimeKind.Utc),
                TemperatureC = 21,
                Summary = "Sunny",
            },
        });
        SetupResponse(HttpStatusCode.OK, payload);
        var client = GetClient();

        // act
        var result = await client.GetWeatherForecastAsync();

        // assert
        var forecast = Assert.Single(result);
        Assert.Equal(21, forecast.TemperatureC);
        Assert.Equal("Sunny", forecast.Summary);
    }

    [Fact]
    public async Task GetWeatherForecastAsync_EmptyJsonArray_ReturnsEmptyArray()
    {
        // arrange
        SetupResponse(HttpStatusCode.OK, "[]");
        var client = GetClient();

        // act
        var result = await client.GetWeatherForecastAsync();

        // assert
        Assert.Empty(result);
    }

    [Fact]
    public async Task GetWeatherForecastAsync_NonSuccessStatus_Throws()
    {
        // arrange
        SetupResponse(HttpStatusCode.InternalServerError);
        var client = GetClient();

        // act + assert
        var ex = await Assert.ThrowsAsync<Exception>(() => client.GetWeatherForecastAsync());
        Assert.Contains("InternalServerError", ex.Message);
    }
}

using Newtonsoft.Json;
using Rxo.Platform.Api.Sandbox.Domain;

namespace Rxo.Platform.Api.Sandbox.Client
{

public class SandboxApiClient
{
    private static readonly JsonSerializer _serializer = JsonSerializer.CreateDefault();

    private readonly HttpClient _client;

    public SandboxApiClient(HttpClient client)
    {
        _client = client;
    }

    public async Task<IWeatherForecast[]> GetWeatherForecastAsync()
    {
        var url = $"{Constants.CurrentVersion}/weather/getweatherforecast";
        var request = new HttpRequestMessage(HttpMethod.Get, url);
        var result = await _client.SendAsync(request).ConfigureAwait(false);
        if (!result.IsSuccessStatusCode)
        {
            throw new Exception($"GetWeatherForecastAsync failed with StatusCode={result.StatusCode}");
        }

        // Stream the response straight into Newtonsoft so we never allocate
        // the full body as a string — important for large forecast payloads.
        using var stream = await result.Content.ReadAsStreamAsync().ConfigureAwait(false);
        using var reader = new StreamReader(stream);
        using var jsonReader = new JsonTextReader(reader);
        return _serializer.Deserialize<WeatherForecast[]>(jsonReader) ?? Array.Empty<WeatherForecast>();
    }
}

