//OPTIONAL/EXPERIMENTAL: Not a usual use case
public class SignatureValidationMiddleware
{
    private readonly RequestDelegate _next;

    public SignatureValidationMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context, ApplicationConfig config)
    {
        if (!context.Request.Path.StartsWithSegments("/api", StringComparison.OrdinalIgnoreCase))
        {
            await _next(context);
            return;
        }

        var signature = context.Request.Headers["x-signature"].FirstOrDefault();
        var error = SignatureValidator.Validate(
            config.Secret,
            signature,
            context.Request.Method,
            context.Request.Path
        );

        if (error != null)
        {
            context.Response.StatusCode = 401;
            await context.Response.WriteAsync(error);
            return;
        }

        await _next(context);
    }
}

public static class SignatureValidationMiddlewareExtensions
{
    public static IApplicationBuilder UseApiSignatureValidation(this IApplicationBuilder app)
    {
        return app.UseMiddleware<SignatureValidationMiddleware>();
    }
}

