    options.AddPolicy("AllowAll",
        builder =>
        {
            builder.WithOrigins(applicationConfig.BaseUrl)
                .AllowCredentials()
                .AllowAnyMethod()
                .AllowAnyHeader();
        });
});
#endregion

#region autofac
// Replaces the default DI container with Autofac.
// ServiceModule  → registers all Services-layer dependencies.
// RepositoryModule → registers all data-access dependencies (self-contained, opaque to Host).
builder.Host.UseServiceProviderFactory(new AutofacServiceProviderFactory())
    .ConfigureContainer<ContainerBuilder>(c => {
        c.RegisterModule(new ServiceModule());
        c.RegisterModule(new RepositoryModule(configuration));
    });
#endregion

var app = builder.Build();

#region pipeline
// HTTP request pipeline — order is significant:
// 1. Development tools (Swagger UI, developer exception page) — non-production only
// 2. HTTPS redirection
// 3. Routing — must precede auth so route metadata is available to auth middleware
// 4. Signature validation — verifies x-signature HMAC from Express proxy; rejects /api/* requests without valid signature (401)
// 5. Authentication — validates the bearer token and populates HttpContext.User
// 6. Authorization — enforces policies declared on endpoints/controllers
// 6. CORS — applies the AllowAll policy registered above
// 7. Versioned endpoint groups — REST and gRPC endpoints under /{version}/
// 8. gRPC-Web — wraps gRPC calls so they work over HTTP/1.1 / browser fetch
// 9. Health check — lightweight liveness probe at /healthcheck
if (app.Environment.IsDevelopment())
{
    app.UseDeveloperExceptionPage();
}

// 5. Authentication — validates the bearer token and populates HttpContext.User
// 6. Authorization — enforces policies declared on endpoints/controllers
// 6. CORS — applies the AllowAll policy registered above
// 7. Versioned endpoint groups — REST and gRPC endpoints under /{version}/
// 8. gRPC-Web — wraps gRPC calls so they work over HTTP/1.1 / browser fetch
// 9. Health check — lightweight liveness probe at /healthcheck
if (app.Environment.IsDevelopment())
{
    app.UseDeveloperExceptionPage();
}

app.UseSwagger();
app.UseSwaggerUI();
app.UseRouting();
//OPTIONAL/EXPERIMENTAL: enforce signature validation
//app.UseApiSignatureValidation();
app.UseAuthentication();
app.UseAuthorization();
app.UseCors("AllowAll");
//qualify in case of conflicts
RxoAuthAuthorization::Rxo.Auth.Authorization.RxoAuthorizationExtensions.UseRxoAuthorization(app);

// Endpoint registration pattern: open a versioned route group here, then chain
// the Service-layer Map*Endpoints extension that owns the feature's routes.
// One MapGroup per (version, transport); one Map*Endpoints extension per
// feature area. Adding a new feature = new MapXxxEndpoints in
// Services/Infrastructure + one chained call here. Do not register individual
// routes in Program.cs.
app.MapGroup($"/api/{Constants.CurrentVersion}")
    //.RequireAuthorization("Bearer")
    .MapWeatherEndpoints();

app.MapGroup($"/api/{Constants.CurrentVersion}")
    //.RequireAuthorization("Bearer")
    .MapGrpcEndpoints();

// Activates attribute-routed controllers (e.g. WeatherController). Route
// prefix + version are declared per-controller via [Route("api/v1/...")] so
// no MapGroup wrapper is needed here.
app.MapControllers();

// OPTIONAL SETUP: GRPC OPTIONS
app.UseGrpcWeb(new GrpcWebOptions { DefaultEnabled = true });

app.MapGet("/healthcheck", () =>
{
    return "200";
})
.WithName("Diagnostics");
#endregion

#region Database Upgrade
async Task RunDatabaseUpgradeAsync(WebApplication app)
{
    using var scope = app.Services.CreateScope();
    var dbSetup = scope.ServiceProvider.GetService<SandboxDbSetUp>();
    if (dbSetup != null)
    {
        await dbSetup.PerformUpgrade();
    }

