﻿using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using Serilog;


// ReSharper disable once CheckNamespace
namespace Rxo.Platform.Api.Sandbox.Host
{

public static class RxoAuthBearerExtensions
{
    private readonly static string RxoAuthenticationSection = "RxoAuthentication";

    /// <summary>
    /// Fetches OIDC signing keys directly from the authority's JWKS endpoint.
    /// </summary>
    public async static Task<IList<SecurityKey>> FetchSigningKeys(string authorityUrl)
    {
        using var handler = new HttpClientHandler
        {
            ServerCertificateCustomValidationCallback = HttpClientHandler.DangerousAcceptAnyServerCertificateValidator
        };
        using var client = new HttpClient(handler);

        var metadataUrl = $"{authorityUrl}/.well-known/openid-configuration";
        var discoveryJson = await client.GetStringAsync(metadataUrl);
        var discovery = System.Text.Json.JsonDocument.Parse(discoveryJson);
        var jwksUri = discovery.RootElement.GetProperty("jwks_uri").GetString();

        Log.Information("FetchSigningKeys: jwks_uri={JwksUri}", jwksUri);

        var jwksJson = await client.GetStringAsync(jwksUri);
        var jwks = new JsonWebKeySet(jwksJson);
        var signingKeys = jwks.GetSigningKeys();

        Log.Information("FetchSigningKeys: resolved {Count} signing keys", signingKeys.Count);
        return signingKeys;
    }

    /// <summary>
    /// Adds Bearer Token Authentication to MVC App
    /// </summary>
    public static void AddRxoAuthBearerTokenAuthentication(this IServiceCollection services,
        IConfiguration configuration,
        Action<RxoAuthBearerOptions> optionsAction)
    {
        if (configuration == null)
            throw new ArgumentNullException(nameof(configuration));

        if (optionsAction == null)
            throw new ArgumentNullException(nameof(optionsAction));
        var env = configuration.GetValue<string>("xpo:environment");
        var issuerName = configuration.GetValue<string>($"{RxoAuthenticationSection}:IssuerName");
        var xpoAuthOptions = new RxoAuthBearerOptions();
        xpoAuthOptions.AuthorityUrl = configuration.GetValue<string>($"{RxoAuthenticationSection}:AuthorityUrl");
        xpoAuthOptions.Audience = configuration.GetValue<string>($"{RxoAuthenticationSection}:Audience");
        xpoAuthOptions.ClientId = configuration.GetValue<string>($"{RxoAuthenticationSection}:ClientId");
        xpoAuthOptions.ClientSecret = configuration.GetValue<string>($"{RxoAuthenticationSection}:ClientSecret");
        xpoAuthOptions.NameClaimType = "sub";
        xpoAuthOptions.RoleClaimType = "role";
        optionsAction(xpoAuthOptions);

        // Fetch signing keys directly at startup — bypasses ConfigurationManager
        // which has been failing to resolve keys despite valid JWKS.
        var authorityUrl = xpoAuthOptions.AuthorityUrl ?? ResolveEnvironment(env);
        var signingKeys = FetchSigningKeys(authorityUrl);

        services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
        .AddJwtBearer(options =>
        {
            options.Events = new JwtBearerEvents
            {
                OnMessageReceived = context =>
                {
                    return xpoAuthOptions.OnMessageReceived != null ?
                        xpoAuthOptions.OnMessageReceived(context) :
                        Task.CompletedTask;
                },
                OnTokenValidated = context =>
                {
                    return xpoAuthOptions.OnTokenValidated != null ?
                        xpoAuthOptions.OnTokenValidated(context) :
                        Task.CompletedTask;
                },
                OnAuthenticationFailed = context =>
                {
                    return xpoAuthOptions.OnAuthenticationFailed != null ?
                        xpoAuthOptions.OnAuthenticationFailed(context) :
                        Task.CompletedTask;
                },
            };

            options.Audience = xpoAuthOptions.Audience;
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = false,
                ValidIssuer = issuerName,
                ValidateAudience = !string.IsNullOrEmpty(xpoAuthOptions.Audience),
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                IssuerSigningKeys = xpoAuthOptions.SigningKeys,
                NameClaimType = xpoAuthOptions.NameClaimType,
                RoleClaimType = xpoAuthOptions.RoleClaimType,
                TokenDecryptionKey = xpoAuthOptions.EnryptKey,
                ClockSkew = TimeSpan.Zero
            };
        });
    }

    private static readonly HashSet<string> LowerEnvironments = new HashSet<string>
    {
       "dev",
       "main",
       "perf",
       "qa",
       "qahotfix",
       "uat",
       "uathotfix",
       "hotfix",
       "staging",
    };

    private static string ResolveEnvironment(string env)
    {
        if ("prod" == env.ToLower())
        {
            return "https://login.id.rxo.com/";
        }

        if ("dev" == env.ToLower())
        {
            return "https://login-dev.id.rxo.com/";
        }

        if ("perf" == env.ToLower())
        {
            return "https://login-perf.id.rxo.com/";
        }

        if (LowerEnvironments.Contains(env.ToLower()))
        {
            return "https://login-sandbox.id.rxo.com/";
        }

        if ("Local" == env.ToLower())
        {
            return "https://localhost:5000/";
        }

        return null;
    }
}

