﻿using Google.Apis.Auth.OAuth2;
using Google.Cloud.SecretManager.V1;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Npgsql;

namespace Rxo.Platform.Api.Sandbox.Repository.Infrastructure.Data
{

/// <summary>
/// Per-operation source of open <see cref="NpgsqlConnection"/>s. Repositories
/// take a dependency on this interface and call <see cref="GetConnectionAsync"/>
/// once per query — they never hold the connection across calls. Implementations
/// are registered <c>InstancePerDependency</c> so connection state cannot leak
/// between requests (see <see cref="RepositoryModule"/>).
/// </summary>
public interface ISandboxDbExecutorFactory
{
    Task<NpgsqlConnection> GetConnectionAsync();
}

/// <summary>
/// Google Cloud-aware Postgres connection factory. The base connection string
/// comes from <c>ConnectionStrings:sandbox</c>; the password is injected at
/// connection-open time using one of three strategies, selected per environment:
///
/// <list type="bullet">
/// <item>
///   <term>Static password (default)</term>
///   <description>
///     Neither feature flag is set — the connection string is used verbatim
///     (password baked in). Intended for local development against a Postgres
///     instance whose credentials are not sensitive.
///   </description>
/// </item>
/// <item>
///   <term>IAM token (<c>db:pgEnableTokenPassword=1</c>)</term>
///   <description>
///     <see cref="GenerateTokenAsync"/> uses <c>GoogleCredential.GetApplicationDefaultAsync</c>
///     to obtain an OAuth2 access token scoped to
///     <c>https://www.googleapis.com/auth/sqlservice.login</c> and uses it as
///     the Postgres password. Cloud SQL must have IAM Authentication enabled
///     and the workload's service account must be a Cloud SQL IAM user. Tokens
///     are short-lived; Npgsql's password provider is invoked again whenever
///     a new connection needs one, so rotation is automatic.
///   </description>
/// </item>
/// <item>
///   <term>Secret Manager (<c>db:pgEnableSecretPassword=1</c>)</term>
///   <description>
///     <see cref="GetSecretPasswordAsync"/> fetches the <c>latest</c> version
///     of the secret named by <c>db:pgSecretName</c> from project
///     <c>CloudProjectId</c> via <see cref="SecretManagerServiceClient"/>. The
///     resulting UTF-8 payload becomes the Postgres password. Used when the
///     database authenticates via a long-lived password we still want managed
///     outside the deployment manifest.
///   </description>
/// </item>
/// </list>
///
/// Flags are mutually exclusive — token wins if both are set. Both strategies
/// rely on Google Application Default Credentials, so the host workload
/// (GKE / Cloud Run / local <c>gcloud auth application-default login</c>) must
/// be authenticated.
///
/// The <see cref="NpgsqlDataSource"/> is built once (lazily) and reused; only
/// the password is resolved per-connection through Npgsql's password provider.
/// </summary>
public class SandboxDbExecutorFactory : ISandboxDbExecutorFactory
{
    private readonly Lazy<NpgsqlDataSource> _dataSource;
    private readonly Lazy<SecretManagerServiceClient> _client;
    private readonly string _connectionStringName = "Sandbox";
    private bool _useTokenPassword;
    private bool _useSecretPassword;
    private string _secretName;
    private readonly string _projectId;
    private string _connectionString = null;
    private ILogger<SandboxDbExecutorFactory> _logger;


    public SandboxDbExecutorFactory(IConfiguration config, ILogger<SandboxDbExecutorFactory> logger)
    {
        _connectionString = config.GetValue<string>($"ConnectionStrings:{_connectionStringName}");
        _useTokenPassword = config.GetValue<string>($"db:pgEnableTokenPassword") == "1";
        _useSecretPassword = config.GetValue<string>($"db:pgEnableSecretPassword") == "1";
        _secretName = config.GetValue<string>($"db:pgSecretName");
        _projectId = config.GetValue<string>("CloudProjectId");
        _client = new Lazy<SecretManagerServiceClient>(() => SecretManagerServiceClient.Create());
        _dataSource = new Lazy<NpgsqlDataSource>(() => CreateConnection(_connectionString));
        _logger = logger;
    }

    public string ConnectionString => _connectionString;

    public async Task<string> ConnectionStringWithPasswordAsync()
    {
        var sb = new NpgsqlConnectionStringBuilder(_connectionString);
        if (_useTokenPassword)
        {
            sb.Password = await GenerateTokenAsync(default);
        }
        else if (_useSecretPassword)
        {
            sb.Password = await GetSecretPasswordAsync(default);
        }
        return sb.ConnectionString;
    }


    public async Task<NpgsqlConnection> GetConnectionAsync()
    {
        return await _dataSource.Value.OpenConnectionAsync().ConfigureAwait(false);
    }

    /// <summary>
    /// Builds the singleton-per-factory <see cref="NpgsqlDataSource"/>. When a
    /// password-injection strategy is enabled, <see cref="NpgsqlDataSourceBuilder.UsePasswordProvider"/>
    /// is registered with the async callback (<see cref="GenerateTokenAsync"/> or
    /// <see cref="GetSecretPasswordAsync"/>); Npgsql then invokes the callback
    /// each time it needs a password to open a new connection. The sync overload
    /// is intentionally <c>NotImplementedException</c> — all consumers go through
    /// the async path, and the sync path would force blocking IO on the auth
    /// token / Secret Manager call.
    /// </summary>
    public NpgsqlDataSource CreateConnection(string connectionString)
    {
        var builder = new NpgsqlDataSourceBuilder(connectionString);
        if (_useTokenPassword)
        {
            builder.UsePasswordProvider((builder) =>
            {
                throw new NotImplementedException();
            }, async (builder, ct) =>
            {
                return await GenerateTokenAsync(ct);
            });
        }
        else if (_useSecretPassword)
        {
            builder.UsePasswordProvider((builder) =>
            {
                throw new NotImplementedException();
            }, async (builder, ct) =>
            {
                return await GetSecretPasswordAsync(ct);
            });
        }
        builder.EnableDynamicJson();
        builder.ConfigureJsonOptions(InterfaceMapper.ConfiguredOptions);

        return builder.Build();
    }

    /// <summary>
    /// Returns a fresh OAuth2 access token from Application Default Credentials,
    /// scoped to Cloud SQL IAM login (<c>sqlservice.login</c>). Used as the
    /// Postgres password when <c>db:pgEnableTokenPassword=1</c>.
    /// Cloud SQL must have IAM database authentication enabled; the running
    /// workload's service account must be granted the Cloud SQL Instance User
    /// role and mapped to a Postgres user with the same email.
    /// </summary>
    public async Task<string> GenerateTokenAsync(CancellationToken ct)
    {
        var credential = await GoogleCredential.GetApplicationDefaultAsync(ct);
        if (credential.IsCreateScopedRequired)
        {
            credential = credential.CreateScoped("https://www.googleapis.com/auth/sqlservice.login");
        }
        var token = await credential.UnderlyingCredential.GetAccessTokenForRequestAsync(cancellationToken: ct);
        _logger.LogInformation($"RxoPgMessagingDbExecutorFactory:GenerateTokenAsync");
        return token;
    }

    /// <summary>
    /// Fetches the <c>latest</c> version of the secret named by
    /// <c>db:pgSecretName</c> from Secret Manager in project
    /// <c>CloudProjectId</c> and returns the UTF-8 decoded payload as the
    /// Postgres password. Used when <c>db:pgEnableSecretPassword=1</c>.
    /// The workload's service account needs the
    /// <c>roles/secretmanager.secretAccessor</c> role on the secret.
    /// </summary>
    public async Task<string> GetSecretPasswordAsync(CancellationToken ct)
    {
        var secretVersionName = new SecretVersionName(_projectId, _secretName, "latest");
        var result = await _client.Value.AccessSecretVersionAsync(secretVersionName);
        var secretValue = result.Payload.Data.ToStringUtf8();
        _logger.LogInformation($"RxoPgMessagingDbExecutorFactory:GetSecretPasswordAsync({secretValue?.Length})");
        return secretValue;
    }
}

﻿using System.Text.Json;
using System.Text.Json.Serialization;

namespace Rxo.Platform.Api.Sandbox.Repository.Infrastructure
{

public class InterfaceMapper<TInterface, TImplementation> : JsonConverter<TInterface> where TImplementation : TInterface
{
    public override TInterface Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        return JsonSerializer.Deserialize<TImplementation>(ref reader, options);
    }
    public override void Write(Utf8JsonWriter writer, TInterface value, JsonSerializerOptions options)
    {
        // Serialize the object as its concrete type
        JsonSerializer.Serialize(writer, (TImplementation)value, options);
    }
}

public static class InterfaceMapper
{   
    public readonly static JsonSerializerOptions ConfiguredOptions = Configure(new JsonSerializerOptions());
    public static JsonSerializerOptions Configure(JsonSerializerOptions options)
    {
        // Configure the JsonSerializerOptions globally
        options.PropertyNamingPolicy = JsonNamingPolicy.CamelCase;
        options.WriteIndented = false;
        options.PropertyNameCaseInsensitive = true;
        options.DefaultIgnoreCondition = JsonIgnoreCondition.Never;

        // Add the custom converter for interface to concrete type mapping
        //options.Converters.Add(new InterfaceMapper<Domain.IMessage, Domain.Message>());;

        return options;
    }
}

