﻿using Autofac;
using Microsoft.Extensions.Configuration;
using Rxo.Platform.Api.Sandbox.Repository.Infrastructure.Data;

namespace Rxo.Platform.Api.Sandbox.Repository
{

/// <summary>
/// Autofac module that owns all data-access registrations. Loaded by
/// <c>Program.cs</c>; the Services layer never references this module directly.
///
/// Lifetime rules:
/// <list type="bullet">
///   <item><description><see cref="SandboxDbExecutorFactory"/> — <c>InstancePerDependency</c>: each repository gets its own factory so connection state cannot leak between requests.</description></item>
///   <item><description><see cref="SandboxDbSetUp"/> — <c>SingleInstance</c>: migration runner; resolved once at startup then discarded.</description></item>
///   <item><description>Repositories — <c>InstancePerDependency</c>: short-lived, disposed after each handler call.</description></item>
/// </list>
/// </summary>
public class RepositoryModule : Module
{
    private readonly IConfiguration _config;

    public RepositoryModule(IConfiguration config)
    {
        _config = config;
    }

    protected override void Load(ContainerBuilder builder)
    {
        base.Load(builder);
        RegisterDatabase(builder);
        RegisterRepositories(builder);
    }

    private void RegisterDatabase(ContainerBuilder builder)
    {
        builder.RegisterType<SandboxDbExecutorFactory>().As<ISandboxDbExecutorFactory>().InstancePerDependency();
        builder.RegisterType<SandboxDbSetUp>().AsImplementedInterfaces().AsSelf().SingleInstance();
    }

    private void RegisterRepositories(ContainerBuilder builder)
    {
        builder.RegisterType<WeatherRepository>().As<IWeatherRepository>().InstancePerDependency();
    }
}

﻿using DbUp;
using DbUp.Engine;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Rxo.Platform.Api.Sandbox.Repository.Infrastructure.Data;
using System.Reflection;

namespace Rxo.Platform.Api.Sandbox.Repository
{

/// <summary>
/// DbUp-based schema migration runner. Called once at startup from
/// <c>Program.cs</c> before the HTTP pipeline begins accepting requests.
///
/// Script execution order per run:
/// <list type="number">
///   <item><description>Inline DDL — creates <c>public.schemaversions</c> table + sequence if absent.</description></item>
///   <item><description>Pre-scripts (<c>a_001.pgsql</c>) — always run; used for idempotent setup (e.g. clearing cache tables).</description></item>
///   <item><description>Migration scripts (<c>Scaffolding/{nnn}/*.pgsql</c>, excluding a_ and z_) — run once, journaled in <c>schemaversions</c>.</description></item>
///   <item><description>Post-scripts (<c>z_001.pgsql</c>) — always run; used for grants and post-migration cleanup.</description></item>
/// </list>
///
/// All <c>.pgsql</c> files must be set to <c>Build Action: Embedded Resource</c>.
/// </summary>
public class SandboxDbSetUp
{
    private readonly SandboxDbExecutorFactory _connectionFactory;
    private readonly ILogger<SandboxDbSetUp> _logger;

    public SandboxDbSetUp(IConfiguration config, ILogger<SandboxDbSetUp> logger, ILogger<SandboxDbExecutorFactory> dbLogger)
    {
        _connectionFactory = new SandboxDbExecutorFactory(config, dbLogger);
        _logger = logger;
    }

    /// <summary>
    /// Runs all pending migration scripts against the configured Postgres database.
    /// Returns <c>true</c> on success; logs and returns <c>false</c> on failure.
    /// </summary>
    public async Task<bool> PerformUpgrade()
    {
        var connectionString = await _connectionFactory.ConnectionStringWithPasswordAsync();
        EnsureDatabase.For.PostgresqlDatabase(connectionString);

        // Inline DDL: ensure the DbUp journal table and its sequence exist.
        var schemaVersionsSeq = @"CREATE SEQUENCE IF NOT EXISTS public.schemaversions_schemaversionsid_seq
            START WITH 1
                INCREMENT BY 1
                NO MINVALUE
                NO MAXVALUE
            CACHE 1;
        ";

        var schemaVersions = @"CREATE TABLE IF NOT EXISTS public.schemaversions (
                SchemaVersionsId INTEGER NOT NULL PRIMARY KEY DEFAULT nextval('public.schemaversions_schemaversionsid_seq'),
                ScriptName TEXT NOT NULL,
                Applied TIMESTAMP(2) WITH TIME ZONE NULL
            );
            ALTER TABLE public.schemaversions OWNER TO readwrite;
            GRANT SELECT ON public.schemaversions TO readonly;

            ALTER SEQUENCE public.schemaversions_schemaversionsid_seq OWNER TO readwrite;
            GRANT USAGE, SELECT ON public.schemaversions_schemaversionsid_seq TO readonly;
        ";

        var result = DeployChanges.To
            .PostgresqlDatabase(connectionString)
            .WithScript("01_schemaVersionsSeq", schemaVersionsSeq)
            .WithScript("02_schemaversions", schemaVersions)
            .JournalToPostgresqlTable("public", "schemaversions")
            // Pre-scripts: always run (a_001.pgsql)
            .WithScriptsEmbeddedInAssembly(Assembly.GetExecutingAssembly(), s => s.EndsWith("a_001.pgsql"), new SqlScriptOptions { ScriptType = DbUp.Support.ScriptType.RunAlways })
            // Migration scripts: run once, journaled
            .WithScriptsEmbeddedInAssembly(Assembly.GetExecutingAssembly(), s => s.EndsWith(".pgsql") && !s.EndsWith("a_001.pgsql") && !s.EndsWith("z_001.pgsql"))
            // Post-scripts: always run (z_001.pgsql)
            .WithScriptsEmbeddedInAssembly(Assembly.GetExecutingAssembly(), s => s.EndsWith("z_001.pgsql"), new SqlScriptOptions { ScriptType = DbUp.Support.ScriptType.RunAlways })
            .LogToConsole()
            .Build()
            .PerformUpgrade();

        _logger.LogInformation(
            result.Successful
                ? $"{nameof(SandboxDbSetUp)}.{nameof(PerformUpgrade)}: Successful=true"
                : $"{nameof(SandboxDbSetUp)}.{nameof(PerformUpgrade)}: Successful=false, Error={result.Error.Message}");

        return result.Successful;
    }
}

