namespace Xpo.Auth.Data.Caching
{

/// <summary>
/// Base implementation of <see cref="ICacheProvider"/> that delegates to
/// <see cref="IRxoRedisCache"/> (the platform Redis client).
/// Concrete providers inherit this class, supply a feature-scoped key prefix
/// via <see cref="QualifyKey"/>, and optionally override
/// <see cref="CacheExpiration"/> to change the TTL.
///
/// All reads and writes flow through the qualified key so entries from
/// different providers never collide in a shared Redis instance.
/// </summary>
public abstract class CacheProviderBase : ICacheProvider
{
    private readonly IRxoRedisCache _cache;

    protected CacheProviderBase(IRxoRedisCache cache)
    {
        _cache = cache;
    }

    /// <summary>
    /// TTL applied to every entry written by this provider.
    /// Defaults to 5 minutes; override in a subclass to change it.
    /// </summary>
    protected virtual TimeSpan CacheExpiration { get; set; } = TimeSpan.FromMinutes(5);

    /// <inheritdoc/>
    public async Task<T> GetAsync<T>(string key)
    {
        var itemKey = QualifyKey(key);
        return await _cache.GetAsync<T>(itemKey, ttl: CacheExpiration);
    }

    /// <inheritdoc/>
    public async Task SetAsync<T>(string key, T app)
    {
        var itemKey = QualifyKey(key);
        await _cache.SetAsync<T>(itemKey, app, ttl: CacheExpiration, groupKey: GroupKey());
    }

    /// <inheritdoc/>
    public async Task RemoveAsync(string key)
    {
        var itemKey = QualifyKey(key);
        await _cache.DeleteAsync(itemKey);
    }

    /// <inheritdoc/>
    public async Task ClearAsync()
    {
        await _cache.DeleteAsync(GroupKey());
    }

    /// <summary>
    /// Transforms a caller-supplied short key into a fully-qualified Redis key
    /// scoped to this provider's feature namespace.
    /// Convention: <c>{domain}:{feature}:{key}</c> — e.g. <c>sandbox:hello-world:my-key</c>.
    /// </summary>
    protected abstract string QualifyKey(string key);

    /// <inheritdoc/>
    public abstract string GroupKey();
}

