/// <summary>
/// Redis cache provider for the hello-world feature namespace.
/// All keys are prefixed with <c>sandbox:hello-world:</c> so they are
/// isolated from every other feature's cache entries.
///
/// Group key: <c>sandbox:hello-world:group</c> — deleting this key (via
/// <see cref="ICacheProvider.ClearAsync"/>) evicts the entire namespace at once.
/// </summary>
public class HelloWorldCacheProvider : CacheProviderBase
{
    public HelloWorldCacheProvider(IRxoRedisCache cache) : base(cache)
    {
    }

    /// <summary>
    /// Qualifies <paramref name="key"/> as <c>sandbox:hello-world:{key}</c>.
    /// Pattern: <c>{domain}:{feature}:{key}</c>.
    /// </summary>
    protected override string QualifyKey(string key) => $"sandbox:hello-world:{key}";

    /// <summary>
    /// Group key that owns all entries in this namespace.
    /// Resolved as <c>sandbox:hello-world:group</c>.
    /// </summary>
    public override string GroupKey() => QualifyKey("group");
}

/// <summary>
/// Abstracts a scoped Redis cache namespace for a single feature area.
/// Each implementation owns a key prefix and a group key so its entries
/// can be invalidated independently without affecting other cache namespaces.
/// Implementations are registered as singletons and auto-discovered by
/// <c>ServiceModule</c> via assembly scanning.
/// </summary>
public interface ICacheProvider
{
    /// <summary>
    /// Retrieves a cached value by key, or returns the default for
    /// <typeparamref name="T"/> when the key is absent or expired.
    /// </summary>
    Task<T> GetAsync<T>(string key);

    /// <summary>
    /// Writes a value into the cache under the given key, associated with
    /// this provider's group key so bulk invalidation is possible via
    /// <see cref="ClearAsync"/>.
    /// </summary>
    Task SetAsync<T>(string key, T app);

    /// <summary>
    /// Removes a single entry by its unqualified key.
    /// The implementation qualifies the key with the feature prefix before deletion.
    /// </summary>
    Task RemoveAsync(string key);

    /// <summary>
    /// Removes all entries that belong to this provider's group key,
    /// effectively flushing the entire feature namespace.
    /// </summary>
    Task ClearAsync();

    /// <summary>
    /// Returns the group key that logically owns all entries written by this
    /// provider. Deleting the group key cascades to every associated entry.
    /// </summary>
    string GroupKey();
}

