    // Dispatched via IApiService.SendAsync; CqrsModule's assembly scan registers
    // the handler so endpoints/controllers never resolve it directly.

/// <summary>
/// TRequest — implements <see cref="IWeatherForecast"/> so endpoints can bind the
/// request body straight onto the command without a separate DTO.
/// </summary>
public class SaveWeatherForecastCommand : IAsyncCommand, IWeatherForecast
{
    [Required]
    public DateTime StartDate { get; set; }

    [Required]
    public DateTime EndDate { get; set; }

    [Range(-100, 100, ErrorMessage = "TemperatureC must be a plausible Celsius value.")]
    public int TemperatureC { get; set; }

    [StringLength(120)]
    public string? Summary { get; set; }
}

