using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Rxo.Platform.Api.Sandbox.Domain;
using Rxo.Platform.Api.Sandbox.Services.CommandHandlers;
using Rxo.Platform.Api.Sandbox.Services.Infrastructure;
using Rxo.Platform.Api.Sandbox.Services.QueryHandlers;
using Rxo.Platform.Api.Sandbox.Services.Services;

namespace Rxo.Platform.Api.Sandbox.Services.Controllers
{
    /// <summary>
    /// Controller-based mirror of <see cref="WeatherEndpoints"/>. Demonstrates
    /// the MVC variant of the same registration pattern: the route prefix is
    /// declared via <see cref="RouteAttribute"/> (versioned via
    /// <see cref="Constants.v2"/>) rather than a <c>MapGroup</c> in <c>Program.cs</c>.
    ///
    /// Both styles dispatch through <see cref="IApiService"/> so the underlying
    /// CQRS handler is identical regardless of the transport surface chosen.
    ///
    /// Activation: requires <c>app.MapControllers()</c> in the <c>Program.cs</c>
    /// pipeline (not currently wired). Until then this controller is registered
    /// but unrouted.
    /// </summary>
    [ApiController]
    [Route($"api/{Constants.v2}/[controller]")]

public class WeatherController : ControllerBase
{
    private readonly IApiService _apiService;

    public WeatherController(IApiService apiService)
    {
        _apiService = apiService ?? throw new ArgumentNullException(nameof(apiService));
    }

    /// <summary>
    /// GET /api/v1/weather/forecast — returns weather forecast entries for the current day.
    /// Mirrors <c>WeatherEndpoints.MapWeatherEndpoints</c>'s <c>weather/forecast</c> route.
    /// </summary>
    [HttpGet("forecast")]
    [ProducesResponseType(typeof(List<GetWeatherQueryResult>), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    //[Authorize(Policy = Policies.Weather)]
    public async Task<IActionResult> Forecast()
    {
        var query = new GetWeatherQuery();
        var validation = new Validation<GetWeatherQuery>().Validate(query);
        if (!validation.IsValid)
        {
            return BadRequest(validation.ValidationResults);
        }
        var result = await _apiService.RequestAsync(query).ConfigureAwait(false);
        return Ok(result);
    }

    /// <summary>
    /// POST /api/v2/weather/forecast — persists a single weather forecast entry.
    /// Mirrors the <c>MapPost</c> in <see cref="WeatherEndpoints"/>; both dispatch
    /// the same <see cref="SaveWeatherForecastCommand"/> through <see cref="IApiService"/>.
    /// </summary>
    [HttpPost("forecast")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    //[Authorize(Policy = Policies.Weather)]
    public async Task<IActionResult> Forecast([FromBody] SaveWeatherForecastCommand command)
    {
        var validation = new Validation<SaveWeatherForecastCommand>().Validate(command);
        if (!validation.IsValid)
        {
            return BadRequest(validation.ValidationResults);
        }
        await _apiService.SendAsync(command).ConfigureAwait(false);
        return NoContent();
    }
}

