﻿using System.Security.Cryptography;
using System.Text;

namespace Rxo.Platform.Api.Sandbox.Services.Infrastructure
{

public static class SignatureValidator
{
    public static string Validate(string secret, string csignature, string cmethod, string cpath)
    {
        try
        {
            var split = csignature.Split(':');
            var payload = split[0];
            var signature = split[1];
            var data = payload.Split(".");
            var method = data[0];
            var path = data[1]; 
            var then = long.Parse(data[2]);
            var now = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            var max = 1000 * 60;
            var signed = ReSign(secret, payload);
            if (signed != signature)
            {
                return $"SignatureValidator: invalid signature";
            }
            if (now - then >= max)
            {
                return "SignatureValidator: request timeout";
            }
            if (method.ToLower() != cmethod.ToLower())
            {
                return "SignatureValidator: invalid method";
            }
            if (path.ToLower() != cpath.ToLower())
            {
                return "SignatureValidator: invalid path";
            }
        }
        catch
        {
            //
        }
        return null;
    }
    public static string ReSign(string secret, string payload)
    {
        using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(secret));
        var hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(payload));

        return Convert.ToHexString(hash).ToLower();
    }
}

﻿using Microsoft.AspNetCore.Http;
using System.ComponentModel.DataAnnotations;

namespace Rxo.Platform.Api.Sandbox.Services.Infrastructure
{

/// <summary>
/// Lightweight pre-dispatch validator for CQRS commands and queries.
/// Called from endpoints (or controllers) before handing the request to
/// <see cref="Services.IApiService"/>; if validation fails, the endpoint
/// short-circuits and returns <see cref="Result"/> (a 400 with the failure
/// reasons) instead of invoking the handler.
///
/// Validation is data-annotation based: decorate fields on the
/// command/query itself with <see cref="ValidationAttribute"/>-derived
/// attributes (e.g. <c>[Required]</c>, <c>[Range]</c>, <c>[StringLength]</c>).
/// Because the command/query is bound directly from the request body or
/// route parameters in light APIs, this lets us validate the request shape
/// without introducing a separate request DTO. Reserve a dedicated DTO for
/// the cases where the wire shape genuinely diverges from the handler input.
///
/// Typical endpoint usage:
/// <code>
/// var validation = new Validation&lt;GetWeatherQuery&gt;().Validate(query);
/// if (!validation.IsValid) return validation.Result;
/// var result = await apiService.RequestAsync(query);
/// </code>
/// </summary>
public class Validation<T>
{
    /// <summary>Per-property failures populated by <see cref="Validate"/>; empty when valid.</summary>
    public List<ValidationResult> ValidationResults = new List<ValidationResult>();

    /// <summary>True when the most recent <see cref="Validate"/> call passed all annotations.</summary>
    public bool IsValid { get; set; }

    /// <summary>
    /// Runs every <see cref="ValidationAttribute"/> declared on <paramref name="model"/>
    /// (validateAllProperties: true). Returns <c>this</c> so the call chains directly
    /// into an <c>IsValid</c> check at the endpoint.
    /// </summary>
    public Validation<T> Validate(T model)
    {
        var context = new ValidationContext(model, null, null);
        IsValid = Validator.TryValidateObject(model, context, ValidationResults, true);
        return this;
    }

    /// <summary>
    /// Minimal-API friendly response: 200 OK if valid, 400 BadRequest with
    /// <c>{ Reasons = [...] }</c> otherwise. Endpoints typically only return
    /// this on the failure path — the success branch invokes the handler instead.
    /// </summary>
    public IResult Result => IsValid ? Results.Ok() : Results.BadRequest(new {
        Reasons = ValidationResults
    });
}

