/// <summary>
/// Endpoint registration follows a two-step convention:
///
///   1. <c>Program.cs</c> creates a versioned route group:
///      <c>app.MapGroup($"/api/{Constants.CurrentVersion}")</c>
///   2. The group is then extended by a feature-scoped extension method in
///      this Infrastructure namespace (e.g. <see cref="MapWeatherEndpoints"/>),
///      which attaches the actual routes, policies, and OpenAPI metadata.
///
/// One extension method per feature area; one route group per API version.
/// Endpoints depend on <see cref="IApiService"/> for handler dispatch — they
/// never resolve query/command handlers directly.
/// </summary>
public static class WeatherEndpoints
{
    public static string BasePath = "weather";

    /// <summary>
    /// Attaches the Weather feature's routes to a versioned group registered
    /// in <c>Program.cs</c>. Routes are relative to the parent group's prefix
    /// (e.g. final path is <c>/api/v1/weather/forecast</c>).
    /// </summary>
    public static IEndpointRouteBuilder MapWeatherEndpoints(this IEndpointRouteBuilder endpoints)
    {
        endpoints.MapGet($"{BasePath}/forecast", async (HttpContext context, IApiService apiService) =>
        {
            var query = new GetWeatherQuery();
            var validation = new Validation<GetWeatherQuery>().Validate(query);
            if (!validation.IsValid)
            {
                return validation.Result;
            }
            var result = await apiService.RequestAsync(query).ConfigureAwait(false);
            return Results.Ok(result);
        })
        //.RequireAuthorization(Policies.Weather)
        .Produces<List<GetWeatherQueryResult>>()
        .WithName("GetWeatherForecast")
        .WithSummary("Returns weather forecast entries for the current day")
        .WithTags("Weather")
        .WithOpenApi();

        endpoints.MapPost($"{BasePath}/forecast", async (SaveWeatherForecastCommand command, IApiService apiService) =>
        {
            // Command binds directly from the request body (it implements
            // IWeatherForecast and carries the [Required]/[Range] attributes).
            var validation = new Validation<SaveWeatherForecastCommand>().Validate(command);
            if (!validation.IsValid)
            {
                return validation.Result;
            }
            await apiService.SendAsync(command).ConfigureAwait(false);
            return Results.NoContent();
        })
        //.RequireAuthorization(Policies.Weather)
        .Produces(StatusCodes.Status204NoContent)
        .ProducesValidationProblem()
        .WithName("SaveWeatherForecast")
        .WithSummary("Persists a single weather forecast entry")
        .WithTags("Weather")
        .WithOpenApi();

        return endpoints;
    }
}

