namespace Rxo.Platform.Api.Sandbox.Services.QueryHandlers
{
    // Query handler convention — three types per query, always in the same shape:
    //
    //   1. TResult  — the response shape returned to the caller.
    //                 (e.g. GetWeatherQueryResult). Implements a Domain interface
    //                 when the result is part of the API's shared contract.
    //   2. TRequest — the query record/class, implements IQuery<TResult> (or
    //                 ICommand for the command side). Validation attributes live
    //                 here (see Validation<T>) since endpoints bind request data
    //                 directly onto this type.
    //   3. Handler  — class implementing IQueryHandlerAsync<TRequest, TResult>
    //                 (and optionally a feature-specific interface like
    //                 IGetWeatherQueryHandler for direct injection / testing).
    //                 Handlers are discovered and dispatched by IApiService.
    //
    // Layout is a style choice, not a rule: keep all three in one file when the
    // query is small and the types are only used together (the common case, as
    // here), or split into separate files (Result.cs / Query.cs / Handler.cs)
    // under a per-feature subfolder when any of them grows or is reused.
    // CqrsModule scans the assembly either way.

/// <summary>TResult — response shape for <see cref="GetWeatherQuery"/>.</summary>
public class GetWeatherQueryResult : IWeatherForecast
{
    public DateTime StartDate { get; set; }
    public DateTime EndDate { get; set; }
    public int TemperatureC { get; set; }
    public string? Summary { get; set; }
}

/// <summary>TRequest — empty marker query; add validation-attributed fields here as inputs grow.</summary>
public class GetWeatherQuery : IAsyncQuery<List<GetWeatherQueryResult>>
{
}

/// <summary>
/// Feature-specific handler interface. Optional but useful for unit tests
/// that want to mock <c>IGetWeatherQueryHandler</c> directly instead of the
/// generic <c>IQueryHandlerAsync&lt;,&gt;</c>.
/// </summary>
public interface IGetWeatherQueryHandler
{
    Task<List<GetWeatherQueryResult>> Handle(GetWeatherQuery query);
}

/// <summary>
/// Handler — resolved and invoked by <see cref="IApiService.RequestAsync"/>.
/// Depends only on Service-layer abstractions (here <see cref="IWeatherService"/>);
/// never reaches into the Repository layer directly.
/// </summary>
public class GetWeatherQueryHandler : IGetWeatherQueryHandler, IAsyncQueryHandler<GetWeatherQuery, List<GetWeatherQueryResult>>
{
    private readonly IWeatherService _weatherService;

    public GetWeatherQueryHandler(IWeatherService weatherService)
