namespace Rxo.Platform.Api.Sandbox.Services
{

public class ServiceModule : Module
{
    protected override void Load(ContainerBuilder builder)
    {
        base.Load(builder);
        // cqrs
        // IApiService is the CQRS mediator endpoints depend on — it resolves
        // and invokes query/command handlers so endpoints never touch Autofac
        // or handler types directly. CqrsModule scans this assembly and
        // registers every IQueryHandlerAsync<,> / ICommandHandlerAsync<>.
        builder.RegisterType<ApiService>().AsSelf().AsImplementedInterfaces().SingleInstance();
        builder.RegisterAssemblyTypes(System.Reflection.Assembly.GetExecutingAssembly()).AsClosedTypesOf(typeof(IAsyncQueryHandler<,>)).AsImplementedInterfaces().InstancePerLifetimeScope();
        builder.RegisterAssemblyTypes(System.Reflection.Assembly.GetExecutingAssembly()).AsClosedTypesOf(typeof(IAsyncCommandHandler<>)).AsImplementedInterfaces().InstancePerLifetimeScope();
        // event handlers
        builder.RegisterModule(new RxoSubModule(System.Reflection.Assembly.GetExecutingAssembly()));
        // caching — auto-discovers every ICacheProvider implementation in this assembly
        // and registers each as a singleton. No per-provider wiring is required;
        // adding a new XxxCacheProvider that inherits CacheProviderBase is sufficient.
        // Redis is optional: if disabled in config the underlying IRxoRedisCache
        // no-ops, so providers remain injectable but return cached defaults.
        builder.RegisterAssemblyTypes(System.Reflection.Assembly.GetExecutingAssembly()).As(typeof(ICacheProvider)).AsImplementedInterfaces().SingleInstance();
        // services
        builder.RegisterType<WeatherService>().As<IWeatherService>().InstancePerDependency();
    }
}

﻿using Autofac;
using Xpo.Common.Cqrs;

namespace Rxo.Platform.Api.Sandbox.Services.Services
{

/// <summary>
/// CQRS mediator. Endpoints take a dependency on <see cref="IApiService"/>
/// instead of resolving individual handlers, so callers stay decoupled from
/// the concrete <c>IQueryHandlerAsync&lt;,&gt;</c> / <c>ICommandHandlerAsync&lt;&gt;</c>
/// types and from Autofac itself.
///
/// Lifetime: registered as <c>SingleInstance</c> in <see cref="ServiceModule"/>.
/// Per-call, a child <see cref="Autofac.ILifetimeScope"/> is spun up so handler-scoped
/// dependencies (e.g. <c>InstancePerDependency</c> repositories) are disposed
/// after the request/command completes.
///
/// Typical endpoint usage:
/// <code>
/// endpoints.MapGet("foo", async (IApiService api) =>
///     Results.Ok(await api.RequestAsync(new GetFooQuery())));
/// </code>
/// </summary>
public interface IApiService
{
    /// <summary>
    /// Executes a query by locating its <c>IQueryHandlerAsync&lt;TQuery, T&gt;</c>
    /// in DI and invoking <c>HandleAsync</c>. The handler is discovered at runtime
    /// from the query's concrete type — no manual wiring required at the call site.
    /// </summary>
    Task<T> RequestAsync<T>(IAsyncQuery<T> query);

    /// <summary>
    /// Dispatches a command to its <c>ICommandHandlerAsync&lt;T&gt;</c>. Use for
    /// state-changing operations; queries should go through <see cref="RequestAsync"/>.
    /// </summary>
    Task SendAsync<T>(T command) where T : IAsyncCommand;
}

internal class ApiService : IApiService
{
    private readonly ILifetimeScope _lifetimeScope;

    public ApiService(ILifetimeScope lifetimeScope)
    {
        _lifetimeScope = lifetimeScope ?? throw new ArgumentNullException(nameof(lifetimeScope));
    }
    public async Task<T> RequestAsync<T>(IAsyncQuery<T> query)
    {
        query = query ?? throw new ArgumentNullException(nameof(query));
        using (var scope = _lifetimeScope.BeginLifetimeScope())
        {
            // Build the closed generic IQueryHandlerAsync<TQuery, T> from the
            // runtime type of `query` so callers can pass any IQuery<T> without
            // the call site knowing the concrete handler.
            Type type = typeof(IAsyncQueryHandler<,>);
            Type[] typeArgs = { query.GetType(), typeof(T) };
            Type handlerType = type.MakeGenericType(typeArgs);

            // dynamic dispatch avoids reflection on HandleAsync — the runtime
            // binder picks the right overload from the concrete query type.
            dynamic handler = scope.Resolve(handlerType);
            Task<T> task = handler.HandleAsync((dynamic)query);
            return await task.ConfigureAwait(false);
        }
    }

    public Task SendAsync<T>(T command) where T : IAsyncCommand
    {
        command = command ?? throw new ArgumentNullException(nameof(command));
        using (var scope = _lifetimeScope.BeginLifetimeScope())
        {
            scope.TryResolve(out IAsyncCommandHandler<T> handler);
            return handler.Handle(command);
        }
    }
}

