namespace Rxo.Platform.Api.Sandbox.Services.Tests.Infrastructure
{

/// <summary>
/// Spins up a minimal in-memory <see cref="TestServer"/> with routing,
/// JSON, and whatever services the caller adds via <paramref name="servicesHook"/>.
/// Endpoint extension methods are attached through <paramref name="endpointsHook"/>.
/// Lets endpoint tests exercise the real request pipeline without booting Host.
/// </summary>
public abstract class EndpointsTestsBase
{
    protected HttpClient GetTestClient(
        Action<IServiceCollection> servicesHook,
        Action<IEndpointRouteBuilder> endpointsHook)
    {
        var server = new TestServer(new WebHostBuilder()
            .ConfigureServices(services =>
            {
                services.AddRouting();
                servicesHook(services);
            })
            .Configure(app =>
            {
                app.UseRouting();
                app.UseEndpoints(endpointsHook);
            }));
        return server.CreateClient();
    }
}

