namespace Rxo.Platform.Api.Sandbox.Services.Tests.Infrastructure
{

public class WeatherEndpointsTests : EndpointsTestsBase
{
    private readonly Mock<IApiService> _apiService;

    public WeatherEndpointsTests()
    {
        _apiService = new Mock<IApiService>();
    }

    private HttpClient GetClient()
    {
        return GetTestClient(
            services => services.AddSingleton(_apiService.Object),
            endpoints => endpoints.MapWeatherEndpoints());
    }

    [Fact]
    public async Task GetForecast_ReturnsOkWithDispatchedResult()
    {
        // arrange
        var expected = new List<GetWeatherQueryResult>
        {
            new() { StartDate = DateTime.UtcNow, EndDate = DateTime.UtcNow.AddHours(1), TemperatureC = 21, Summary = "Sunny" }
        };
        _apiService
            .Setup(s => s.RequestAsync(It.IsAny<IAsyncQuery<List<GetWeatherQueryResult>>>()))
            .ReturnsAsync(expected);
        var client = GetClient();

        // act
        var response = await client.GetAsync("weather/forecast");
        var body = await response.Content.ReadFromJsonAsync<List<GetWeatherQueryResult>>();

        // assert
        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.NotNull(body);
        Assert.Single(body!);
        Assert.Equal("Sunny", body![0].Summary);
    }

    [Fact]
    public async Task PostForecast_ValidCommand_DispatchesAndReturnsNoContent()
    {
        // arrange
        var payload = new SaveWeatherForecastCommand
        {
            StartDate = new DateTime(2026, 5, 14, 9, 0, 0, DateTimeKind.Utc),
            EndDate = new DateTime(2026, 5, 14, 10, 0, 0, DateTimeKind.Utc),
            TemperatureC = 18,
            Summary = "Partly Cloudy",
        };
        _apiService
            .Setup(s => s.SendAsync(It.IsAny<SaveWeatherForecastCommand>()))
            .Returns(Task.CompletedTask);
        var client = GetClient();

        // act
        var response = await client.PostAsJsonAsync("weather/forecast", payload);

        // assert
        Assert.Equal(HttpStatusCode.NoContent, response.StatusCode);
        _apiService.Verify(s => s.SendAsync(It.Is<SaveWeatherForecastCommand>(c =>
            c.TemperatureC == 18 && c.Summary == "Partly Cloudy")), Times.Once);
    }

    [Fact]
    public async Task PostForecast_InvalidCommand_ReturnsBadRequest_AndDoesNotDispatch()
    {
        // arrange — TemperatureC outside [-100, 100] fails [Range] validation
        var payload = new SaveWeatherForecastCommand
        {
            StartDate = DateTime.UtcNow,
            EndDate = DateTime.UtcNow.AddHours(1),
            TemperatureC = 500,
            Summary = "Impossibly hot",
        };
        var client = GetClient();

        // act
        var response = await client.PostAsJsonAsync("weather/forecast", payload);

        // assert
        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
        _apiService.Verify(s => s.SendAsync(It.IsAny<SaveWeatherForecastCommand>()), Times.Never);
    }
}

