namespace Rxo.Platform.Api.Sandbox.Services.Tests.Services
{

public class WeatherServiceTests
{
    private readonly Mock<IWeatherRepository> _weatherRepository;

    public WeatherServiceTests()
    {
        _weatherRepository = new Mock<IWeatherRepository>();
    }

    private WeatherService GetService()
    {
        return new WeatherService(_weatherRepository.Object);
    }

    [Fact]
    public async Task GetWeatherAsync_MapsEntitiesToDomainForecasts()
    {
        // arrange
        var start = new DateTime(2026, 5, 14, 9, 0, 0, DateTimeKind.Utc);
        var entities = new List<WeatherEntity>
        {
            new() { StartTime = start, EndTime = start.AddHours(1), TemperatureC = 21, Condition = "Sunny" },
        };
        _weatherRepository.Setup(r => r.GetWeatherAsync()).ReturnsAsync(entities);
        var service = GetService();

        // act
        var result = await service.GetWeatherAsync();

        // assert
        var forecast = Assert.Single(result);
        Assert.Equal(start, forecast.StartDate);
        Assert.Equal(start.AddHours(1), forecast.EndDate);
        Assert.Equal(21, forecast.TemperatureC);
        Assert.Equal("Sunny", forecast.Summary);
    }

    [Fact]
    public async Task SaveWeatherAsync_MapsDomainForecastToEntity_AndDelegatesToRepository()
    {
        // arrange
        var forecast = new WeatherForecast
        {
            StartDate = new DateTime(2026, 5, 14, 9, 0, 0, DateTimeKind.Utc),
            EndDate = new DateTime(2026, 5, 14, 10, 0, 0, DateTimeKind.Utc),
            TemperatureC = 18,
            Summary = "Partly Cloudy",
        };
        _weatherRepository
            .Setup(r => r.SaveAsync(It.IsAny<WeatherEntity>()))
            .Returns(Task.CompletedTask);
        var service = GetService();

        // act
        await service.SaveWeatherAsync(forecast);

        // assert
        _weatherRepository.Verify(r => r.SaveAsync(It.Is<WeatherEntity>(e =>
            e.StartTime == forecast.StartDate &&
            e.EndTime == forecast.EndDate &&
            e.TemperatureC == forecast.TemperatureC &&
            e.Condition == forecast.Summary)), Times.Once);
    }
}

