﻿using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Mvc;
using Rxo.Auth.Authentication;

namespace Rxo.Platform.Web.Sandbox.Services.Controllers
{

public class AccountController : ControllerBase
{
    private readonly IRefershTokenService _refreshTokenService;
    private readonly IAuthenticationSchemeProvider _schemeProvider;
    public AccountController(IAuthenticationSchemeProvider schemeProvider, IRefershTokenService refreshTokenService)
    {
        _schemeProvider = schemeProvider;
        _refreshTokenService = refreshTokenService;
    }
    public async Task<IActionResult> Login(string returnUrl)
    {
        var authOptions = new RxoAuthOptions();
        if (authOptions?.AuthenticationScheme == null)
        {
            return new RedirectToActionResult("Error", "Error", new { message  = "Default Scheme is not defined" });
        }
        var props = new AuthenticationProperties
        {
            RedirectUri = returnUrl ?? "/",
            AllowRefresh = true,
        };

        return Challenge(props, authOptions.AuthenticationScheme);
    }

    public async Task<IActionResult> Logout(string returnUrl = "/")
    {
        var authOptions = new RxoAuthOptions();
        if (authOptions.AuthenticationScheme == null)
        {
            return new RedirectToActionResult("Error", "Error", new { message = "Default Scheme is not defined" });
        }
        var props = new AuthenticationProperties
        {
            RedirectUri = returnUrl
        };
        return SignOut(props, authOptions.AuthenticationScheme, authOptions.SignInScheme);
    }

    public async Task<IActionResult> RefreshToken()
    {
        var scheme = await _schemeProvider.GetSchemeAsync("Cookies");
        var schemeName = scheme?.Name ?? scheme?.DisplayName ?? string.Empty;
        var signinScheme = scheme?.Name ?? scheme?.DisplayName ?? string.Empty;
        var authResult = await HttpContext.AuthenticateAsync(signinScheme);
        var accessToken = string.Empty;
        var refreshToken = string.Empty;
        if (authResult?.Principal != null && authResult?.Properties != null)
        {
            // existing token
            accessToken = authResult.Properties.GetTokenValue("access_token");
            refreshToken = authResult.Properties.GetTokenValue("refresh_token");
            var idToken = authResult.Properties.GetTokenValue("id_token");
            if (!string.IsNullOrEmpty(refreshToken) && !string.IsNullOrEmpty(accessToken))
            {
                await _refreshTokenService.RefreshTokenAsync(HttpContext, schemeName, signinScheme, refreshToken, HttpContext.RequestAborted).ConfigureAwait(false);
                // respond with fresh token
                refreshToken = await HttpContext.GetTokenAsync("refresh_token").ConfigureAwait(false);
                accessToken = await HttpContext.GetTokenAsync("access_token").ConfigureAwait(false);
            }
        }

        return Ok(new
        {
            refreshToken,
            accessToken,
        });
    }
}

