    {
        var model = new ReactViewModel()
        {
            ApplicationContext = new ApplicationContextViewModel()
            {
                LoginUrl = Url.Action("Login", "Account", null, Request.Scheme),
                LogoutUrl = Url.Action("Logout", "Account", null, Request.Scheme),
