    {
        var user = new UserContextViewModel();
        if (User.Identity?.IsAuthenticated == true)
        {
            user.UserDetails = new UserDetailsViewModel();
            var claims = User.Claims;
            user.UserId = "";
            user.UserDetails.UserName = User.Claims.FirstOrDefault(c => c.Type == "email")?.Value ?? string.Empty;
            user.UserDetails.FirstName = User.Claims.FirstOrDefault(c => c.Type == "given_name")?.Value ?? string.Empty;
            user.UserDetails.LastName = User.Claims.FirstOrDefault(c => c.Type == "family_name")?.Value ?? string.Empty;
            user.UserDetails.UserId = "";
        };
        return user;
    }

