public static class HelloWorldEndpoints
{
    private const string BasePath = "notification";

    public static IEndpointRouteBuilder MapHelloWorldEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var handler = context.RequestServices.GetRequiredService<ICreateNotificationCommandHandler>();
        var command = await context.Request.ReadFromJsonAsync<CreateNotificationCommand>().ConfigureAwait(false);
        var audit = context.RequestServices.GetRequiredService<IAuditService>();
        await audit.AuditPayloadAsync(nameof(CreateNotificationCommand), command).ConfigureAwait(false);
        var validation = new Validation<CreateNotificationCommand>().Validate(command);
        if (!validation.IsValid)
        {
            return validation.Result;
        }
        var result = await handler.HandleAsync(command).ConfigureAwait(false);
        if (result.GetType() == typeof(Failed))
        {
            return Results.BadRequest(((Failed)result).Reasons);
        }
        return Results.Ok(new
        {
            MessageType = handler.MessageType,
            MessageId = handler.MessageId,
            PublishMessageId = handler.PublishMessageId,
            Success = true,
            IsSuccess = true,
        });
    }
}

