namespace Rxo.Platform.Web.Sandbox.Services.Infrastructure
{

public static class AssetMiddleware
{
    public static void Handle(IApplicationBuilder app)
    {
        app.Use(async (HttpContext context, Func<Task> next) =>
        {
            var reactEndpoint = context.RequestServices.GetRequiredService<IConfiguration>().GetValue<string>("react:url");
            var publicFolder = context.RequestServices.GetRequiredService<IConfiguration>().GetValue<string>("react:publicFolder");
            string url = $"{reactEndpoint}/{publicFolder}{context.Request.Path}?{context.Request.QueryString}";
            var uri = new Uri(url);
            var response = context.Response;
            var headers = context.Request.Headers;
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Get, uri);
            foreach (var header in headers)
            {
                request.Headers.TryAddWithoutValidation(header.Key, header.Value.ToString());
            }
            var result = await client.SendAsync(request).ConfigureAwait(false);
            var contentType = result.Content.Headers.ContentType?.ToString() ?? "text/plain";
            if (!result.IsSuccessStatusCode)
            {
                await response.WriteAsync(result.StatusCode.ToString());
            }
            using (var contentStream = await result.Content.ReadAsStreamAsync().ConfigureAwait(false))
            {
                await contentStream.CopyToAsync(response.Body);
            }
        });
    }
}

﻿using Microsoft.AspNetCore.Mvc;
using System.Text.Json;
using System.Text;
using Microsoft.AspNetCore.Authentication;

namespace Rxo.Platform.Web.Sandbox.Services.Config
{

public class ReactResult : IActionResult
{
    private readonly Object _model;
    public ReactResult(Object model)
    {
        _model = model;
    }

    public async Task ExecuteResultAsync(ActionContext context)
    {
        var reactEndpoint = context.HttpContext.RequestServices.GetRequiredService<IConfiguration>().GetValue<string>("react:url");
        string url = $"{reactEndpoint}{context.HttpContext.Request.Path}?{context.HttpContext.Request.QueryString}";       
        var response = context.HttpContext.Response;
        var headers = context.HttpContext.Request.Headers;
        var accessToken = await context.HttpContext.GetTokenAsync("access_token");
        var refreshToken = await context.HttpContext.GetTokenAsync("refresh_token");
        var client = new HttpClient();
        var options = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            WriteIndented = false,
        };
        var jsonString = JsonSerializer.Serialize(_model, options);
        var content = new StringContent(jsonString, Encoding.UTF8, "application/json");
        var request = new HttpRequestMessage(HttpMethod.Post, url);
        request.Content = content;
        foreach (var header in headers)
        {
            request.Headers.TryAddWithoutValidation(header.Key, header.Value.ToString());
        }
        request.Headers.TryAddWithoutValidation("access_token", accessToken);
        request.Headers.TryAddWithoutValidation("refresh_token", refreshToken);
        var result = await client.SendAsync(request).ConfigureAwait(false);
        var responseData = await result.Content.ReadAsStringAsync().ConfigureAwait(false);
        var contentType = result.Content.Headers.ContentType?.ToString() ?? "text/plain";
        if (!result.IsSuccessStatusCode)
        {
            await response.WriteAsync(result.StatusCode.ToString());
        }
        await response.WriteAsync(responseData);
    }
}

﻿using System.ComponentModel.DataAnnotations;

namespace Rxo.Platform.Web.Sandbox.Services.Infrastructure
{

public class Validation<T>
{
    public List<ValidationResult> ValidationResults = new List<ValidationResult>();
    public bool IsValid { get; set; }
    public Validation<T> Validate(T model)
    {
        var context = new ValidationContext(model, null, null);
        List<ValidationResult> validationResults = new List<ValidationResult>();
        Validator.TryValidateObject(model, context, validationResults, true);
        ValidationResults.AddRange(validationResults);
        IsValid = !ValidationResults.Any(v => !string.IsNullOrEmpty(v.ErrorMessage));
        return this;
    }
    public Validation<T> Validate(IEnumerable<T> models)
    {
        foreach (var model in models)
        {
            Validate(model);
        }
        return this;
    }
    public IResult Result => IsValid ? Results.Ok() : Results.BadRequest(new
    {
        Reasons = ValidationResults
    });
}

