import axios, { AxiosInstance } from 'axios';
import { jwtDecode } from 'jwt-decode';

const refreshTokenAsync = async (token: string, refreshToken: string) => {
  const decoded = jwtDecode(token);
  // 10 minute expiration from now, compare in seconds instead of milliseconds
  const now = Math.floor(Date.now() / 1000) + 60 * 10;
  if (now > decoded.exp) {
    return axios
      .post('/account/refreshtoken')
      .then((response) => {
        if (response.status != 200) {
          console.error(`Failed to refresh Token: ${response.status}. url=/account/refreshtoken`);
        }
        return response.data;
      })
      .then((data) => {
        return {
          refreshToken: data.refreshToken,
          accessToken: data.accessToken,
        };
      });
  }
  return Promise.resolve({
    accessToken: token,
    refreshToken: refreshToken,
  });
};

export const configureClient = ({ baseUrl, apiKey, accessToken, cloudTraceContext, correlationId }: { baseUrl: string; accessToken: string; apiKey: string; cloudTraceContext: string; correlationId: string; }): AxiosInstance => {
  const axiosClient = axios.create({
    baseURL: baseUrl,
    withCredentials: true,
    headers: {
      'Content-Type': 'application/json',
      'x-apikey': apiKey,
      'x-cloud-trace-context': cloudTraceContext,
      'X-telem-correlation-id': correlationId,
    },
  });
  // Add a request interceptor
  axiosClient.interceptors.request.use(
    async (config) => {
      config.headers.Authorization = `Bearer ${accessToken}`;
      return config;
    },
    (error) => {
      return Promise.reject(error);
    },
  );
  return axiosClient;
};

import { useRef } from 'react';
import { AxiosInstance, AxiosRequestConfig } from 'axios';
import { miniStore, type IMiniStore } from '@root/components/shared/miniStore.ts';

export interface IUseAxiosClientResult {
  // Subscribable handles — read with useMiniStore($isLoading) / useMiniStore($error).
  $isLoading: IMiniStore<boolean>;
  $error: IMiniStore<string>;
  request: (options: AxiosRequestConfig) => Promise<any>;
}

export const useAxiosClient = (client: AxiosInstance): IUseAxiosClientResult => {
  // Stores owned here; handles are created once so they stay stable across renders.
  const isLoadingRef = useRef<boolean>(false);
  const errorRef = useRef<string>('');
  const $isLoading = useRef(miniStore.create(isLoadingRef)).current;
  const $error = useRef(miniStore.create(errorRef)).current;

  const request = async (options: AxiosRequestConfig) => {
    if (client == null) {
      $isLoading.set(false);
      $error.set('');
      return null;
    }
    $isLoading.set(true);
    $error.set('');
    return client
      ?.request(options)
      .then((response) => {
        if (response.status != 200) {
          $error.set(`Received response: ${response.status}. url=${options.url}`);
        }
        return response.data;
      })
      .catch((err) => {
        console.error(err);
        $error.set(err);
        return null;
      })
      .finally(() => {
        $isLoading.set(false);
      });
  };

  return {
    $isLoading,
    $error,
    request,
  };
};

