  // Stores owned here; handles created once so they stay stable across renders.
  const initializedRef = useRef<boolean>(false);
  const locationRef = useRef<IGetLocationQueryResult>(null);
  const $initialized = useRef(miniStore.create(initializedRef)).current;
  const $location = useRef(miniStore.create(locationRef)).current;

  useEffect(() => {
    if (accessToken && clientRef.current == null) {
      clientRef.current = configureClient({
        accessToken,
        apiKey: config.apiKey,
        baseUrl: '/api',
        correlationId: null,
        cloudTraceContext: null,
      });
      $initialized.set(true);
    }
  }, [accessToken, clientRef.current]);

  const getLocation = (): Promise<IGetLocationQueryResult> => {
    if (clientRef.current && !$isLoading.get()) {
      return request({
        url: '/v1/location/current',
        method: 'get',
      }).then((data) => {
        $location.set(data as IGetLocationQueryResult);
        return data as IGetLocationQueryResult;
      });
    }
    return Promise.resolve($location.get());
  };

  return {
    $initialized,
    $isLoading,
    $error,
    $location,
    getLocation,
  };
};

