import React from 'react';

const Loadable = ({fallback,component,chunk,...props}): React.ReactNode => {
    const isSSR = typeof window == "undefined";

    if(isSSR || !component) {
        return fallback || <></>;
    }

    const [isLoaded,setIsLoaded] = React.useState(false);
    let compRef = React.useRef(null);
    if (chunk) {
        const manifest = window["__manifest__"];
        Object.keys(manifest).forEach(function(key) {
            if(key.indexOf(chunk) == 0) {
                window["__loadAssets__"](manifest[key], () => {
                    component().then(it => {
                        compRef.current =  it.default;
                        //compRef.current = React.createElement(it.default,props);
                        setIsLoaded(true);
                    })
                });
            }
        });
    } else {
        component().then(it => {
            compRef.current =  it.default;
        })
    }

    const Comp = compRef.current;
    return Comp && isLoaded ? <Comp {...props} /> : fallback;
}
export default Loadable;

