import React, { createContext, use, useContext, useMemo, useRef } from 'react';
import { Theme } from '@mui/material';
import { dark_theme, light_green_theme, rxoc_black_palette, rxoc_green_palette, colors, getThemeStyles } from '@root/theme/theme';
import { miniStore, useMiniStore, type IMiniStore } from '@root/components/shared/miniStore.ts';

export interface ILogger {
  debug: (...args: unknown[]) => void;
  info:  (...args: unknown[]) => void;
  warn:  (...args: unknown[]) => void;
  error: (...args: unknown[]) => void;
}

const DEFAULT_THEME: IPageTheme = {
  activeTheme: '',
  pallete: null,
  colors: null,
  name: 'light',
  current: null,
  styles: null,
};

const DEFAULT_VALUE = {
  $config: null,
  config: {
    isSSR: false,
    initialized: false,
    autologin: false,
    authentication: {
      authorityUrl: '',
      authorityIssuer: '',
      clientId: '',
    },
    environment: {
      name: '',
      region: '',
      applicationName: '',
      cloudTraceContext: '',
      correlationId: '',
    },
    oidc: {
      baseUrl: '',
    },
    adminApiAddress: '',
    apiAddress: '',
    apiKey: '',
  } as IConfiguration,
  $theme: miniStore.create<IPageTheme>({ current: DEFAULT_THEME }),
  basePath: '',
  isSSR: false,
  title: '',
  logger: null as ILogger
} as IApplicationContextType;

export interface IConfiguration {
  isSSR: boolean;
  initialized: boolean;
  autologin: boolean;
  authentication: {
    authorityUrl: string;
    clientId: string;
    authorityIssuer: string;
  };
  environment: {
    name: string;
    region: string;
    applicationName: string;
    cloudTraceContext?: string;
    correlationId?: string;
  };
  oidc: {
    baseUrl: string;
  };
  apiKey: string;
  apiAddress: string;
  adminApiAddress: string;
  basePath: string;
}

export interface IPageTheme {
  activeTheme: string;
  name: string;
  pallete: typeof rxoc_black_palette;
  colors: typeof colors;
  current: Theme;
  styles: ReturnType<typeof getThemeStyles>;
}

export interface IApplicationContextType {
  $config: IMiniStore<IConfiguration>;
  // Subscribable handle — read with useMiniStore($theme).
  $theme: IMiniStore<IPageTheme>;
  basePath: string;
  logger: ILogger,
  isSSR: boolean;
  title: string;
}

/** Resolve a seeded theme (name only) into a fully-populated IPageTheme. Done once at store init. */
const resolveTheme = (theme: IPageTheme): IPageTheme => {
  if (theme.activeTheme == theme.name) {
    return theme;
  }
  if (theme.name == 'dark') {
    return { ...theme, current: dark_theme, colors, pallete: rxoc_black_palette, activeTheme: theme.name, styles: getThemeStyles(dark_theme) };
  }
  return { ...theme, current: light_green_theme, colors, pallete: rxoc_green_palette, activeTheme: theme.name, styles: getThemeStyles(light_green_theme) };
};

export const ConsoleLogger: ILogger = 
{
  debug: (...args: unknown[]) => console.log(...args),
  info:  (...args: unknown[]) => console.info(...args),
  warn:  (...args: unknown[]) => console.warn(...args),
  error: (...args: unknown[]) => console.error(...args),     
}

const fetchConfigAsync = (config: IConfiguration, logger: ILogger) : Promise<IConfiguration> => {
  return new Promise((resolve) => {
    if (config.initialized)
    {
      resolve(config);
      return;
    }
    fetch('/appsettings.json')
    .then((response) => {
      return response.json();
    })
    .then((appsettings) => {
      const _ = { ...config };
      _.adminApiAddress = appsettings['admin-api-address'];
      _.apiKey = appsettings['api-key'];
      _.autologin = appsettings['autologin'] || false;
      _.authentication.authorityIssuer = appsettings['authentication']['authorityissuer'];
      _.authentication.authorityUrl = appsettings['authentication']['authorityurl'];
      _.authentication.clientId = appsettings['authentication']['clientId'];
      _.environment.name = appsettings['xpo']['environment'];
      _.environment.region = appsettings['xpo']['region'];
      _.environment.applicationName = appsettings['xpo']['applicationName'];
      _.apiAddress = appsettings['api-address'];
      _.oidc = { baseUrl: appsettings['oidc']?.baseUrl || '' };
      _.initialized = true;
      resolve(_);
    })
    .catch(e => {
      logger.error('Failed to fetch appsettings.json', e);
      resolve({
        ...config,
        initialized: true,
      } as IConfiguration);
    });
  });
}

const ApplicationContext = createContext<IApplicationContextType>(DEFAULT_VALUE);

export const ApplicationContextProvider = ({ value, children }): React.ReactElement => {
  const initialValue = {
    ...DEFAULT_VALUE,
    ...value,
  } as IApplicationContextType & {
    config: IConfiguration;
  }

  const basePath = initialValue.basePath || '';
  const isSSR = initialValue.isSSR || false;
  const title = initialValue.title;
  const logger = initialValue.logger || ConsoleLogger;
  var configPromise = useMemo(() => fetchConfigAsync(initialValue.config, logger), [initialValue.config, logger]);
  const configMemo = use(configPromise);
  const config = useRef<IConfiguration>(configMemo);
  const $config = miniStore.create<IConfiguration>(config);
  // Store owned here; the handle is created once so it stays stable across renders. The theme is
  // resolved from its seeded name a single time at init — write via $theme.set() to switch at runtime.
  const themeRef = useRef<IPageTheme>(resolveTheme((value?.theme as IPageTheme) ?? DEFAULT_THEME));
  const $theme = miniStore.create(themeRef);

  console.debug(`ApplicationContext Initialized ${$config.get().initialized}`);
  return (
    <ApplicationContext.Provider value={{ $config, $theme, basePath, isSSR, title, logger }}>
      {children}
    </ApplicationContext.Provider>
  );
};

export const useApplicationContext = () => {
  return useContext(ApplicationContext);
};

/**
 * The public contract of the context.
 * Add the return type of each domain client hook as a named property.
 *
 * Example:
 *   userClient: ReturnType<typeof useUserClient>;
 *   productClient: ReturnType<typeof useProductClient>;
 */
interface IAxiosContextType {
  weatherClient: ReturnType<typeof useWeatherClient>;
  locationClient: ReturnType<typeof useLocationClient>;
}

const DEFAULT_VALUE = {} as IAxiosContextType;

const AxiosContext = createContext<IAxiosContextType>(DEFAULT_VALUE);

/**
 * Instantiates all domain client hooks and makes them available to the tree.
 * The `value` prop is used to inject overrides in tests.
 *
 * Add new clients here as the app grows:
 *   const userClient = useUserClient();
 *   const productClient = useProductClient();
 *
 * Then include them in the provider value:
 *   <AxiosContext.Provider value={{ ...initialValue, userClient, productClient }}>
 */
export const AxiosContextProvider = ({ value, children }): React.ReactElement => {
  const initialValue = { ...DEFAULT_VALUE, ...value };
  const weatherClient = useWeatherClient();
  const locationClient = useLocationClient();

  return (
    <AxiosContext.Provider value={{ ...initialValue, weatherClient, locationClient }}>
      {children}
    </AxiosContext.Provider>
  );
};

/**
 * Hook for consuming the AxiosContext.
 * Destructure the client(s) you need, then destructure the client interface:
 *
 *   const { userClient } = useAxiosContext();
 *   const { isLoading, error, users, getUsers } = userClient;
 */
export const useAxiosContext = () => {
  return useContext(AxiosContext);
};

export interface IToastNotification {
  showToastMessage: boolean;
  toastMessage: string;
  toastMessageType: 'success' | 'info' | 'warning' | 'error';
}

const DEFAULT_TOAST: IToastNotification = {
  showToastMessage: false,
  toastMessage: '',
  toastMessageType: 'info',
};

export interface INotificationContext {
  setToastMessage(message: string, type: 'success' | 'info' | 'warning' | 'error'): void;
  // Subscribable handle — read with useMiniStore($toast), never read the whole context for the value.
  $toast: IMiniStore<IToastNotification>;
}

const DEFAULT_VALUE: INotificationContext = {
  setToastMessage() {},
  $toast: miniStore.create({ current: DEFAULT_TOAST }),
};

const NotificationContext = createContext<INotificationContext>(DEFAULT_VALUE);

export const NotificationContextProvider = ({ value, children }): React.ReactElement => {
  const seeded = { ...DEFAULT_VALUE, ...value } as INotificationContext;

  // The value lives in a useRef so re-renders don't reset it; the store handle is created once and stays stable.
  const toastRef = useRef<IToastNotification>(seeded.$toast?.get() ?? DEFAULT_TOAST);
  const $toast = miniStore.create(toastRef);

  const contextValue = useMemo<INotificationContext>(
    () => ({
      $toast,
      setToastMessage: (message, type) => {
        $toast.set({
          toastMessage: message,
          toastMessageType: type,
          showToastMessage: message.length > 0,
        });
      },
    }),
    [$toast],
  );

  return <NotificationContext.Provider value={contextValue}>{children}</NotificationContext.Provider>;
};

export const useNotificationContext = () => {
  return useContext(NotificationContext);
};

export interface IUser {
  userId: string;
  userName: string;
  firstName: string;
  lastName: string;
}

export interface ISignoutResponse {
  error?: string;
  returnUrl?: string;
}

export interface ISigninResponse {
  error?: string;
  accessToken?: string;
  returnUrl?: string;
}

/**
 * Public contract of UserContext.
 *
 * accessToken     — the OIDC Bearer token. Two sources (first one wins):
 *                     1. PKCE flow — set by signInCallback / signInSilentCallback after
 *                        a successful login or silent renewal.
 *                     2. Bootstrap injection — passed in via the `value` prop
 *                        (initialValue.accessToken + initialValue.user). Two callers:
 *                          • SSR: server maps req.oidc session → window.WEBPACK_ENTRY_DATA.
 *                          • Web module: host passes token + user via __initialize_web_component.
 *                        In both cases a synthetic oidc-client-ts User is stored in the
 *                        UserManager so isUserLoggedIn() returns true without PKCE.
 *                   Once set, the token cascades into userinfo fetch, permissions fetch,
 *                   and isLoggedIn resolution. Consumers read it via useUserContext().
 * initialized     — true once UserManager has been created and isLoggedIn has been resolved.
 *                   Gate all auth-dependent logic on this flag.
 * hasPermissions  — true once permissions are settled, regardless of login state:
 *                     • logged in  → fetched from the API and stored in the permissions map.
 *                     • logged out → empty map applied as default.
 *                   Always becomes true after config is ready. Use alongside `initialized`
 *                   as the signal that the app bootstrap is complete.
 * isLoggedIn      — true only when UserManager confirms an active session, user info is
 *                   populated, and hasPermissions is true. Consumers rely on this for auth gates.
 * hasPermission   — checks a specific permission key against the resolved permissions map.
 *                   Always returns false before hasPermissions is true.
 */
export interface IUserContextType {
  // Subscribable handles — read with useMiniStore($x) in the consuming component.
  $user: IMiniStore<IUser>;
  $accessToken: IMiniStore<string>;
  $initialized: IMiniStore<boolean>;
  $hasPermissions: IMiniStore<boolean>;
  $isLoggedIn: IMiniStore<boolean>;
  hasPermission: (permission: string) => boolean;
  signIn(returnUrl?: string): Promise<void>;
  signOut(): void;
  signOutCallback(): Promise<ISignoutResponse>;
  signInCallback(returnUrl?: string): Promise<ISigninResponse>;
  signInSilentCallback(): Promise<ISigninResponse>;
}

/**
 * Permission keys used across the app.
 * Always import from here — never hardcode permission strings in routes or components.
 * Pass a value from this map to AuthorizedRoute's `permission` prop or `hasPermission()`.
 */
export const Permissions = {
  Weather: 'weather',
};

const DEFAULT_VALUE = {
  $user: miniStore.create<IUser>({ current: null }),
  $accessToken: miniStore.create<string>({ current: '' }),
  $initialized: miniStore.create<boolean>({ current: false }),
  $hasPermissions: miniStore.create<boolean>({ current: false }),
  $isLoggedIn: miniStore.create<boolean>({ current: false }),
  hasPermission: (_k) => false,
  signIn() { return Promise.resolve(); },
  signOut() {},
  signOutCallback() { return Promise.resolve({} as ISignoutResponse); },
  signInCallback() { return Promise.resolve({} as ISigninResponse); },
  signInSilentCallback() { return Promise.resolve({} as ISigninResponse); },
  // seed values — consumed by the provider to initialize the stores / use() promises
  user: null,
  accessToken: '',
  permissions: {}
} as IUserContextType & {
  user: IUser;
  accessToken: string;
  permissions: Record<string, boolean>;
}

// ---------------------------------------------------------------------------
// Standalone auth helpers — take UserManager as an argument so they have no
// component coupling and can be unit-tested independently.
// ---------------------------------------------------------------------------

/** Initiates PKCE sign-in redirect. `returnUrl` is stored in OIDC state and
 *  recovered in signInCallback so the user lands back on the right page. */
const signIn = (userManager: UserManager, returnUrl: string = '/'): Promise<void> => {
  return userManager.signinRedirect({ state: { returnUrl } as ISignoutResponse });
};

/** Initiates sign-out redirect. No return value — the browser navigates away. */
const signOut = (userManager: UserManager): void => {
  userManager.signoutRedirect();
};

/** Returns true if the OIDC session exists and the token has not expired. Used
 *  by effect 4 to resolve `isLoggedIn` after initialization. */
const isUserLoggedIn = (userManager: UserManager): Promise<boolean> => {
  return userManager.getUser().then((user) => {
    return !!user && !user.expired;
  });
};

/** Handles the post-sign-out redirect. Extracts `returnUrl` from the OIDC
 *  response so the caller can redirect the user to the correct destination. */
const signOutCallback = (userManager: UserManager): Promise<ISignoutResponse> => {
  return userManager.signoutCallback().then((signoutResponse) => ({
    returnUrl: signoutResponse['returnUrl'] || '/',
  } as ISignoutResponse));
};

const fetchUserAsync = (user: IUser, accessToken: string, config: IConfiguration, logger: ILogger) :  Promise<IUser> => {
  return new Promise((resolve) => {
    if (user || !accessToken || !config?.initialized || accessToken === 'AccessTokenHidden')
    {
      resolve(user);
      return;
    }
    fetch(config.authentication.authorityUrl + '/connect/userinfo', {
      headers: { Authorization: 'Bearer ' + accessToken },
    })
    .then((r) => {
      return r.json();
    })
    .then((u) => {
      if (u)
      {
        resolve({
          userId: u['external_identifier'],
          userName: u['email'],
          firstName: u['given_name'],
          lastName: u['family_name'],
        } as IUser);
      }
      resolve({} as IUser);
    })
    .catch(e => {
      logger.error('Failed to get user info:' + e);
      resolve({} as IUser);
    });
  });
};

const fetchUserManagerASync = (userManager: UserManager, user: IUser, accessToken: string, config: IConfiguration, logger: ILogger) : Promise<UserManager> =>
{
  return new Promise((resolve) => {
    if (userManager)
    {
      resolve(userManager);
      return;
    }
    const oidcConfig = {
      authority: config?.authentication?.authorityUrl,
      client_id: config?.authentication?.clientId,
      redirect_uri: typeof window != "undefined" ? window.location.origin + '/auth' : `${config.oidc?.baseUrl}/auth`,
      response_type: 'code',
      scope: 'openid email profile xpo-auth-api rxo-platform-api-sandbox',
      post_logout_redirect_uri: typeof window != "undefined" ? window.location.origin + '/postsignout' : `${config.oidc?.baseUrl}/postsignout`,
      userStore: typeof window != "undefined" ? new WebStorageStateStore({ store: window.localStorage }) : null,
      automaticSilentRenew: false,
    };
    const manager = new UserManager(oidcConfig);
    if (!user)
    {
      resolve(manager);
      return;
    }
    try
    {
      const ssrUser = new User({
        access_token: accessToken,
        token_type: 'Bearer',
        scope: 'openid email profile xpo-auth-api rxo-platform-api-sandbox',
        expires_at: Math.floor(Date.now() / 1000) + 3600,
        profile: {
          sub: user.userId,
          email: user.userName,
          given_name: user.firstName,
          family_name: user.lastName,
          iss: config.authentication.authorityUrl,
          aud: config.authentication.clientId,
          iat: Math.floor(Date.now() / 1000),
          exp: Math.floor(Date.now() / 1000) + 3600,
        },
      });
      manager.storeUser(ssrUser).then(() => {
        resolve(manager);
      })
      .catch(e => {
        logger.error('Error creating UserManager', e);
        resolve(manager);
      });
    }
    catch(e)
    {
      logger.error('Error creating UserManager', e);
      resolve(manager);
    }
  });
}

const fetchPermissionsAsync = (permissions: Record<string, boolean>, accessToken: string, config: IConfiguration, logger: ILogger) : Promise<Record<string, boolean>> => {
  return new Promise((resolve) => {
    if (permissions) {
      resolve(permissions);
      return;
    }
    if (!accessToken || !config?.initialized || accessToken === 'AccessTokenHidden')
    {
      resolve({});
      return;
    }
    fetch(config.adminApiAddress + '/profile/permissions', {
      headers: {
        Authorization: 'Bearer ' + accessToken,
        'x-apikey': config.apiKey,
      },
    })
    .then((r) => {
      return r.json();
    })
    .then((r) => {
      if (r?.permissions?.length) {
        const perms: Record<string, boolean> = {};
        r.permissions.forEach((k: string) => { perms[k] = true; });
        resolve(perms);
      }
      else
      {
        resolve({});
      }
    })
    .catch(e => {
      logger.error('Failed to get permissions:' + e);
      resolve({});
    });
  });
};

/** Handles the PKCE redirect callback after login. Extracts the access token
 *  and the `returnUrl` stored in OIDC state. The provider calls setAccessToken
 *  with the result, which cascades into userinfo and permissions fetches. */
const signInCallback = (userManager: UserManager): Promise<ISigninResponse> => {
  return userManager
    .signinRedirectCallback()
    .then((user?) => ({
      returnUrl: user?.state['returnUrl'] || '/',
      accessToken: user?.access_token,
    } as ISigninResponse))
    .catch((err) => {
      console.error('Sign in callback error', err);
      return { error: err } as ISigninResponse;
    });
};

/** Performs a silent token renewal via the OIDC silent renew endpoint.
 *  On success the provider updates accessToken, refreshing all downstream state. */
const signInSilentCallback = (userManager: UserManager): Promise<ISigninResponse> => {
  return userManager
    .signinSilent()
    .then((user?) => ({
      accessToken: user?.access_token,
    } as ISigninResponse))
    .catch((err) => {
      console.error('Silent renew error', err);
      return { error: err } as ISigninResponse;
    });
};

const UserContext = createContext<IUserContextType>(DEFAULT_VALUE);

export const UserContextProvider = ({ value, children }): React.ReactElement => {
  const initialValue = { ...DEFAULT_VALUE, ...value } as typeof DEFAULT_VALUE;
  const { $config, logger } = useApplicationContext();
  const config = useMiniStore($config);

  // accessToken owns the bootstrap cascade: the provider subscribes to it so a token write
  // re-renders this component, which re-runs the useMemo promises below and re-suspends use().
  const accessTokenRef = useRef<string>(initialValue.accessToken);
  const $accessToken = miniStore.create(accessTokenRef);
  const accessToken = useMiniStore($accessToken);

  //fetch — memoize promises so use() receives stable references across renders
  const userPromise = useMemo(
    () => {return fetchUserAsync(initialValue.user, accessToken, config, logger); },
    [accessToken]
  );
  const userManagerPromise = useMemo(
    () => fetchUserManagerASync(null, initialValue.user, accessToken, config, logger),
    [accessToken]
  );
  const permissionsPromise = useMemo(
    () => fetchPermissionsAsync(initialValue.permissions, accessToken, config, logger),
    [accessToken]
  );

  const userMemo = use(userPromise);
  const userManager = use(userManagerPromise);
  const permissions = use(permissionsPromise);
  const isLoggedInPromise = useMemo(() => isUserLoggedIn(userManager), [userManager, accessToken]);
  const isLoggedInMemo = use(isLoggedInPromise);

  // Stores initialized from the first-render use() results so SSR / first paint is correct
  // without waiting for an effect; the effect below re-syncs them when the token changes.
  const $user = miniStore.create<IUser>({ current: userMemo });
  const $isLoggedIn = miniStore.create<boolean>({ current: isLoggedInMemo });
  const $hasPermissions = miniStore.create<boolean>({ current: permissions != null });
  const $initialized = miniStore.create<boolean>({ current: permissions != null && userManager != null });

  useEffect(() => {
    $isLoggedIn.set(isLoggedInMemo);
    $user.set(userMemo);
    $hasPermissions.set(permissions != null);
    $initialized.set(permissions != null && userManager != null);
  },[accessToken]);

  logger.debug('UserContext Initialized', { userManager: userManager != null, hasPermissions: permissions != null, isLoggedIn: isLoggedInMemo });
  return (
    <UserContext.Provider
      value={{
        $user,
        $accessToken,
        $initialized,
        $isLoggedIn,
        $hasPermissions,
        hasPermission(k: string) {
          return permissions[k] === true;
        },
        signIn(returnUrl?: string) {
          return signIn(userManager, returnUrl);
        },
        signOut() {
          signOut(userManager);
        },
        signOutCallback() {
          return signOutCallback(userManager);
        },
        signInCallback() {
          return signInCallback(userManager).then((r) => {
            $accessToken.set(r.accessToken);
            return r;
          });
        },
        signInSilentCallback() {
          return signInSilentCallback(userManager).then((r) => {
            $accessToken.set(r.accessToken);
            return r;
          });
        },
      }}
    >
      {children}
    </UserContext.Provider>
  );
};

export const useUserContext = () => {
  return useContext(UserContext);
};

window.__loadedAssets__ = window.__loadedAssets__ || [];
window.__loadAssets__ = window.__loadAssets__ || function(asset, callback) {

    if (window.__loadedAssets__.indexOf(asset) >= 0) {
      if (typeof callback === "function")
      {
        callback();
        return;
      }
    }
    window.__loadedAssets__.push(asset);
