import { Request, Response, NextFunction } from 'express';
import crypto from "crypto";
import http from "http";
import { pipeline } from "stream";


const agent = new http.Agent({
  keepAlive: true,
  maxSockets: 100,
});

function getSignature(req: Request)
{
    const secret = req.serverConfig.authentication.secret;
    var random = crypto.randomBytes(16).toString("hex");
    const payload = `${req.method}.${req.path}.${Date.now()}.${random}`;

    const signature = crypto
        .createHmac("sha256", secret)
        .update(payload)
        .digest("hex");
    return `${payload}:${signature}`;
}

export const apiProxyMiddleware = () => {
    return async (req: Request, res: Response, next: NextFunction) => {
        if (!staticPathPattern.test(req.path)) {
            return next();
        }
        const logger = req.logger;
        try {
            const targetUrl = `${req.serverConfig["api-address"]}${req.originalUrl}`;
            const upstream = await fetch(targetUrl, {
                method: req.method,
                headers: {
                    Authorization: "Bearer " + req.userContext?.accessToken,
                    "x-signature": getSignature(req),
                    host: "127.0.0.1:80",
                },
                body: req.method !== "GET" && req.method !== "HEAD" ? (req as any) : undefined,
                duplex: "half",
                agent,
            } as any);

            // Copy status
            res.status(upstream.status);

            // Copy headers
            upstream.headers.forEach((value, key) => {
                res.setHeader(key, value);
            });

            // Stream response
            if (upstream.body) {
                pipeline(upstream.body, res, (err) => {
                if (err) logger.error("Pipeline error:", err);
            });
            } else {
                res.end();
            }
        } catch (err) {
            logger.error(`API proxy error:${req.serverConfig["api-address"]}${req.originalUrl}`, { error: err });
            res.status(502).send("Bad Gateway");
        }
    };
};

