import { Request, Response, NextFunction } from 'express';
import { EncryptJWT  } from 'jose';
import { createPrivateKey } from 'crypto';


export const COOKIE_NAME = 'rxo_ssit';
const DEFAULT_TTL_SECONDS = 300; // 5 minutes

/**
 * Middleware that manages a short-lived, HttpOnly nested JWT identity cookie.
 *
 * Token structure (sign-then-encrypt):
 *   Inner — JWS signed with HS256 using the shared secret.
 *            Carries iss, aud, exp, iat, identity claims, and permissions.
 *   Outer — JWE encrypted with dir + A256GCM (authenticated encryption).
 *            cty: 'JWT' marks the envelope as a nested JWT.
 *
 * - Authenticated session  → issues the cookie.
 * - No session / expired   → clears the cookie.
 *
 * Both the signing and encryption key are derived by hex-decoding
 * `authentication.secret` → 32 bytes (256-bit key).
 * The .NET API decrypts and validates using the same key via
 * TokenDecryptionKey + IssuerSigningKey in TokenValidationParameters.
 *
 * Depends on userContextMiddleware running first to populate req.userContext.
 */
export function jwtIdentityMiddleware(ttlSeconds = DEFAULT_TTL_SECONDS) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const { accessToken, userInfo, permissions } = req.userContext;

    if (!accessToken) {
      res.clearCookie(COOKIE_NAME, { path: '/' });
      return next();
    }

    try
    {
      const { environment } = req.serverConfig.xpo;
      const { secret, clientId } = req.serverConfig.authentication;
      const key = Buffer.from(secret, 'base64');
      const payload = {
        sub:         userInfo?.upn ?? userInfo?.sub,
        upn:         userInfo?.upn,
        email:       userInfo?.email,
        given_name:  userInfo?.given_name,
        family_name: userInfo?.family_name,
      };
      permissions.forEach((permission) => {
        payload["permission"] = permission;
      });

      // Outer: encrypted envelope (JWE) — makes payload opaque in transit/logs
      const token = await new EncryptJWT(payload)
        .setIssuedAt()
        .setIssuer(clientId)
        .setAudience(clientId)
        .setExpirationTime(`${ttlSeconds}s`)
        .setProtectedHeader({ alg: 'dir', enc: 'A256GCM' })
        .encrypt(key);

      const isLocal = environment === 'local';
      res.cookie(COOKIE_NAME, token, {
        httpOnly: true,
        secure:   true,
        sameSite: isLocal ? 'none' : 'strict',
        maxAge:   ttlSeconds * 1000,
        path:     '/',
      });
    }
    catch(err)
    {
      req.logger.error('Failed to create JWT identity cookie', { error: err });
    }
    next();
  };
}

