export function createLogger(config: IApplicationConfig): ILogger {
  const env = config.xpo.environment?.toLowerCase();

  if (env === 'local' || !config.cloudProjectId) {
    return ConsoleLogger;
  }

  const gcpTransport = new LoggingWinston({
    projectId: config.cloudProjectId,
    logName:   config.xpo.applicationName,
    labels:    { ApplicationName: config.xpo.applicationName, environment: config.xpo.environment },
  });

  return winston.createLogger({
    level: 'info',
    transports: [
      new winston.transports.Console({
        format: winston.format.combine(
          winston.format.colorize(),
          winston.format.simple(),
        ),
      }),
      gcpTransport,
    ],
  });
}

