const parsedTemplate = template(
  fs.readFileSync(path.normalize(__dirname + '/index.html')).toString('utf-8'),
);

interface IUserContextTypeWithPermissions extends IUserContextType {
  permissions: Record<string, boolean>;
}

// Returns the seeding shape passed to ApplicationContextProvider's `value` prop (plain `theme`,
// not the `$theme` handle the provider builds). Inferred type — not IApplicationContextType.
function GetApplicationContext(req: Request)
{
  var config = req.serverConfig;
  const applicationContext = {
      config: {
        isSSR: true,
        initialized: true,
        autologin: false,
        authentication: {
          authorityIssuer: config.authentication.authorityIssuer,
          authorityUrl: config.authentication.authorityurl,
          clientId: config.authentication.clientId
        },
        environment: {
          name: config.xpo.environment,
          applicationName: config.xpo.applicationName,
          region: config.xpo.region,
        },
        apiKey: config['api-key'],
        apiAddress: config['api-address'],
        adminApiAddress: config['admin-api-address']
      },
      theme: {
        name: 'light',
      },
      basePath: config.basePath,
      title: 'Rxo Platform Web Sandbox',
      isSSR: true,
    };

  return applicationContext;
}

// Returns the seeding shape passed to UserContextProvider's `value` prop (plain user/accessToken/
// permissions used to initialize the stores), not the handle-based IUserContextType.
function GetUserContext(req: Request)
{
    const { accessToken, userInfo, permissions } = req.userContext;
    const userContext = {
        user: accessToken ? {
          userId:    userInfo?.upn,
          userName:  userInfo?.email,
          firstName: userInfo?.given_name,
          lastName:  userInfo?.family_name,
        } : null,
        accessToken: accessToken ? accessToken : null,
        permissions: permissions?.reduce((acc, key) => ({ ...acc, [key]: true }), {}),
      };
      return userContext;
}

function flushBody(
  req: Request,
  res: Response
): void {

  var applicationContext = GetApplicationContext(req);
  var logger = req.logger;
  var userContext = GetUserContext(req);
  const state = JSON.stringify({ applicationContext, userContext: {
    ...userContext,
    accessToken: 'AccessTokenHidden', // hide access token from ui
  } }).replace(/</g, '\\u003c');

  const html = parsedTemplate({ title: applicationContext.title, state, entry: 'app', basePath: applicationContext.basePath });
  //split html in half, top half above <app>, middle we flush react app, bottom half </app> and below
  const [head, tail] = html.split('<!--app-->');
  let statusCode = 200;

  const writable = new Writable({
    write(chunk, enc, next) { res.write(chunk, enc); next(); },
    final(next)             { res.write(tail); res.end(); next(); },
  });

  const stream = renderToPipeableStream(
    <StaticRouter location={req.originalUrl}>
      <Suspense fallback={<></>}>
        <ApplicationContextProvider value={applicationContext}>
          <Suspense fallback={<></>}>
            <UserContextProvider value={userContext}>
              <AxiosContextProvider value={{}}>
                <NotificationContextProvider value={{}}>
                  <ErrorBoundary logger={logger}>
                    <AppStart>
                      <Layout>
                        <RouteConfig />
                      </Layout>
                    </AppStart>
                  </ErrorBoundary>
                </NotificationContextProvider>
              </AxiosContextProvider>
            </UserContextProvider>
          </Suspense>
        </ApplicationContextProvider>
      </Suspense>
    </StaticRouter>,
    {
      onShellReady() {
        res.statusCode = statusCode;
        res.setHeader('Content-Type', 'text/html');
        res.write(head);
        stream.pipe(writable);
      },
      onError(err) {
        statusCode = 500;
        req.logger.error('SSR render error', { error: err });
        if (!res.headersSent) res.redirect('/error');
      },
      onAllReady() {},
    },
  );
}

/**
 * SSR render middleware.
 * Reads resolved user identity and permissions from req.userContext (populated
 * by userContextMiddleware), builds provider contexts, then streams the HTML response.
 */
export function ssrRenderMiddleware() {
  const staticPathPattern = /\/(public|assets)/i;
  return (req: Request, res: Response, next: NextFunction) => {
    var config = req.serverConfig;
    var basePathPattern = new RegExp(`^\/${config.basePath}`);
    if (!basePathPattern.test(req.path)) {
      return res.redirect("/" + config.basePath + req.originalUrl);
    }
    if (staticPathPattern.test(req.path)) {
      return next();
    }   
    flushBody(req, res);
  };
}

