async function fetchUserInfo(req: Request, accessToken: string): Promise<IUserInfo | null> {
  try {
    if (!accessToken)
    {
      return null;
    }
    const { authentication, 'api-key': apiKey } = req.serverConfig;
    const url = `${authentication.authorityurl}/connect/userinfo`;
    const response = await fetch(url, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'x-apikey': apiKey,
      },
    });
    if (!response.ok) {
      req.logger.error('Failed to fetch user info', { status: response.status, url });
      return null;
    }
    return await response.json();
  } catch {
    return null;
  }
}

async function fetchPermissions(req: Request, accessToken: string): Promise<string[]> {
  try {
    if (!accessToken)
    {
      return null;
    }
    const { 'admin-api-address': adminApi, 'api-key': apiKey, authentication } = req.serverConfig;
    const url = `${adminApi}/profile/${authentication.clientId}`;
    const response = await fetch(url, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'x-apikey': apiKey,
      },
    });
    if (!response.ok) {
      req.logger.error('Failed to fetch user permissions', { status: response.status, url, accessToken: !accessToken });
      return null;
    }
    const data = await response.json();
    const permissions = data?.permissions as Array<string> || [];
    req.logger.debug('Fetched user permissions', { permissions });
    return permissions;
  } catch (err) {
    req.logger.error('Failed to fetch user permissions', { error: err });
    return null;
  }
}

/**
 * Resolves user identity and permissions from the active OIDC session and
 * attaches them to req.userContext for downstream middleware to consume.
 * Runs once per request — jwt_identity and ssr_render both read from here,
 * avoiding duplicate network calls.
 */
export function userContextMiddleware() {
  return async (req: Request, _res: Response, next: NextFunction) => {
    const oidc = (req as any).oidc;
    const accessToken = oidc.accessToken?.access_token;

    if (!accessToken || !oidc?.isAuthenticated()) {
      req.userContext = { accessToken: null, userInfo: null, permissions: [] };
      return next();
    }

    const [userInfo, permissions] = await Promise.all([
      fetchUserInfo(req, accessToken),
      fetchPermissions(req, accessToken),
    ]);

    req.userContext = { accessToken, userInfo, permissions };
    next();
  };
}

