export const useAxiosService = (client: AxiosInstance) => {
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState("");
    const [response, setRespone] = useState(null);
    const request = async (options: AxiosRequestConfig) => {
        setIsLoading(true);
        setError("");
        setRespone(null);
        client.request(options)
            .then((response)=> {
                if (response.status != 200) {
                    setError(`Received response: ${response.status}. url=${options.url}`);
                }
                return response.data;
            })
            .then((data) => {
                setRespone(data);
            })
            .catch(err => {
                console.error(err);
                setError(err);
            })
            .finally(()=> {
                setIsLoading(false);
            })
    }
    return {    
        isLoading,
        error,
        response,
        request,
    }
}

