const useWeatherService = (): {
  initialized: boolean;
  isLoading: boolean;
  error: string;
  weather: Array<GetWeatherQueryResult>;
  getWeather: () => Promise<Array<GetWeatherQueryResult>>;
} => {
  const { $accessToken } = useUserContext();
  const accessToken = useMiniStore($accessToken);
  const { config } = useApplicationContext();
  const clientRef = useRef(null);
  const [initialized, setInitialized] = useState(false);
  const [weather, setWeather] = useState<Array<GetWeatherQueryResult>>(null);
  const { $isLoading, $error, request } = useAxiosClient(clientRef.current);
  const isLoading = useMiniStore($isLoading);
  const error = useMiniStore($error);

  useEffect(() => {
    if (accessToken && clientRef.current == null) {
      clientRef.current = configureClient({
        accessToken,
        apiKey: config.apiKey,
        baseUrl: config.apiAddress,
        correlationId: config.environment.correlationId,
        cloudTraceContext: config.environment.cloudTraceContext,
      });
      setInitialized(true);
    }
  }, [accessToken, clientRef.current]);

  const getWeather = (): Promise<Array<GetWeatherQueryResult>> => {
    if (weather != null) return Promise.resolve(weather);
    if (clientRef.current && !isLoading) {
      return request({ url: "/v1/weather/forecast", method: 'get' }).then((data) => {
        const mapped = map(data);
        setWeather(mapped);
        return mapped;l
      });
    }
    return Promise.resolve(null);
  };

  return { initialized, isLoading, error, weather, getWeather };
};

