/**
 * Shape of the `detail` payload the host must include when dispatching the
 * "initialize" CustomEvent on the <web_sandbox_mfe> element.
 *
 * user        — pre-populated user info; mapped to UserContext's initial value.
 * accessToken — Bearer token from the host's OIDC session; seeds UserContext.accessToken.
 * basePath    — URL prefix where the component is mounted; stored in ApplicationContext.basePath.
 */
export interface IInitializeEventDetail {
  user: Partial<IUser>;
  accessToken: string;
  basePath: string;
}

/** @deprecated Superseded by IInitializeEventDetail. */
export interface IWebComponent {
  basePath: string;
  accessToken: string;
}

class WebComponent extends HTMLElement {
  static get observedAttributes() {
    return [];
  }

  // Attach Shadow DOM, create the React mount point, and wire up the
  // "initialize" event listener. The element is ready to receive the event
  // as soon as this callback returns.
  connectedCallback() {
    const shadow = this.attachShadow({ mode: "open" });
    const mountPoint = document.createElement("div");
    shadow.appendChild(mountPoint);
    this.renderReact(mountPoint);
  }

  // Re-render when observed attributes change (e.g. basePath, accessToken
  // if promoted to attributes in the future).
  attributeChangedCallback() {
    if (this.shadowRoot) {
      this.renderReact(this.shadowRoot.querySelector("div")!);
    }
  }

  private renderReact(container: HTMLDivElement) {

    const root = ReactDOM.createRoot(container);

    // Wait for the host to dispatch "initialize" before rendering.
    // Maps event detail → UserContext and ApplicationContext initial values,
    // then mounts the full provider stack via <Entry />.
    this.addEventListener("initialize", e => {

      // Seed UserContext with the host-supplied user info and access token.
      // accessToken bypasses the PKCE flow — see UserContext accessToken docs.
      const userContext = {
        user: {
          ...(e["detail"]["user"] || {})
        },
        accessToken: e["detail"]["accessToken"]
      };

      // basePath scopes all internal routes under the host's mount prefix.
      const applicationContext = {
        basePath: e["detail"]["basePath"]
      } as IApplicationContextType;

      const props = { root: container,  userContext, applicationContext };
      root.render(<Entry {...props}/>);
    });

  }
}

