interface context {
    authorityUri: string;
    webApiKey: string;
    client: {
        clientId: string;
        secret: string;
        scope: Array<string>
    },
    user: {
        userName: string;
        password: string;
    },
    serviceProviders: Array<{
        name: string;
        applicationKey: string;
        location: string;
    }>
}

const getContext = (userName: string) : context => {

    const user = config.users.find(u => u.username === userName);
    const client = config.clients.find(c => c.clientId === "auth-rxo-cypress-automation-test");
    return {
        authorityUri: config.authorityUri,
        webApiKey: config.webApiKey,
        client,
        user: {
            userName: user.username,
            password: user.password,
        },
        serviceProviders: config.serviceProviders
    }
}

