  ciTimeoutMinutes: 15,
};

// ── Raw shape (partial — validated below) ─────────────────────────────────────

interface RawPipelines {
  deployPipelineId?: number;
  deletePipelineId?: number;
  ciPipelineId?: number;
  ciTimeoutMinutes?: number;
}

interface RawRepository {
  org?: string;
  project?: string;
  repository?: string;
}

interface RawAzureDevOps {
  apiKeyFile?: string;
  pipelines?: RawPipelines;
  repositories?: Record<string, RawRepository>;
}

interface RawConfig {
  repositoryPath?: string;
  mainBranch?: string;
  branchPrefix?: string;
  azureDevOps?: RawAzureDevOps;
}

function build(): CodeManagerConfig {
  const raw = appSettings as RawConfig;

  if (!raw.repositoryPath) {
    throw new Error('codemanagermcp: appsettings.json is missing "repositoryPath".');
  }

  const ado = raw.azureDevOps;
  if (!ado) {
    throw new Error('codemanagermcp: appsettings.json is missing the "azureDevOps" section.');
  }

  const pipes = ado.pipelines;
  if (!pipes?.deployPipelineId || !pipes?.ciPipelineId) {
    throw new Error(
      'codemanagermcp: appsettings.json is missing "azureDevOps.pipelines.deployPipelineId" or "azureDevOps.pipelines.ciPipelineId".',
    );
  }

  const rawRepos = ado.repositories ?? {};
  const repoKeys = Object.keys(rawRepos);
  if (repoKeys.length === 0) {
    throw new Error(
      'codemanagermcp: appsettings.json "azureDevOps.repositories" map is empty — add at least one entry.',
    );
  }

  const repositories: Record<string, RepositoryMapping> = {};
  for (const key of repoKeys) {
    const r = rawRepos[key];
    if (!r?.org || !r?.project || !r?.repository) {
      throw new Error(
        `codemanagermcp: azureDevOps.repositories["${key}"] is missing "org", "project", or "repository".`,
      );
    }
    repositories[key] = {
      org: r.org,
      project: r.project,
      repository: r.repository,
    };
  }

  return {
    repositoryPath: resolve(raw.repositoryPath),
    mainBranch:   raw.mainBranch   ?? DEFAULTS.mainBranch,
    branchPrefix: raw.branchPrefix ?? DEFAULTS.branchPrefix,
    azureDevOps: {
      apiKeyFile: ado.apiKeyFile,
      pipelines: {
        deployPipelineId: pipes.deployPipelineId,
        deletePipelineId: pipes.deletePipelineId,
        ciPipelineId:     pipes.ciPipelineId,
        ciTimeoutMinutes: pipes.ciTimeoutMinutes ?? DEFAULTS.ciTimeoutMinutes,
      },
      repositories,
    },
  };
}

export const config: CodeManagerConfig = build();

/** Directory holding the running server.js — used for PAT file resolution and the data/ state subfolder. */
export const serverDir: string = dirname(fileURLToPath(import.meta.url));

// ── Repository resolution ─────────────────────────────────────────────────────

/**
 * Resolves a consumer-provided repository key (e.g. "rxoinc/Platform/_git/Rxo.UI.NormalizedAddresses")
 * into the ADO target that key maps to. Throws when the key is unknown.
 */
export function resolveRepository(key: string): AzureDevOpsConfig {
  const entry = config.azureDevOps.repositories[key];
  if (!entry) {
    const known = Object.keys(config.azureDevOps.repositories);
    throw new Error(
      `codemanagermcp: unknown repository "${key}".\n` +
      `Known: ${known.length > 0 ? known.join(', ') : '(none configured)'}`,
    );
  }
  return {
    organization: entry.org,
    project:      entry.project,
    repository:   entry.repository,
    apiKeyFile:   config.azureDevOps.apiKeyFile,
  };
}

/** Returns the resolved branch name for a feature slug. */
export function featureBranch(slug: string): string {
  return `${config.branchPrefix}${slug}`;
}

/** Slugifies a human feature name into a safe branch-name segment. */
export function slugify(name: string): string {
  return name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

import { exec } from 'node:child_process';
import { promisify } from 'node:util';

const execAsync = promisify(exec);

export interface RunResult {
  stdout: string;
  stderr: string;
  exitCode: number;
}

export interface RunOptions {
  /** Working directory for the command. */
  cwd?: string;
  /** Timeout in milliseconds. Default: 120 000 ms. */
  timeoutMs?: number;
  /** Extra environment variables merged over process.env. */
  env?: NodeJS.ProcessEnv;
}

/** Runs a shell command. Never throws — returns exit code + captured output. */
export async function run(command: string, options: RunOptions = {}): Promise<RunResult> {
  const { cwd, timeoutMs = 120_000, env } = options;
  try {
    const { stdout, stderr } = await execAsync(command, {
      cwd,
      timeout: timeoutMs,
      env: { ...process.env, ...env },
      maxBuffer: 10 * 1024 * 1024,
    });
    return { stdout: stdout.trim(), stderr: stderr.trim(), exitCode: 0 };
  } catch (err) {
    const e = err as { stdout?: string; stderr?: string; code?: number | null };
    return {
      stdout: (e.stdout ?? '').trim(),
      stderr: (e.stderr ?? '').trim(),
      exitCode: typeof e.code === 'number' ? e.code : 1,
    };
  }
}

/** Runs a shell command and throws if it exits non-zero. */
export async function mustRun(command: string, options: RunOptions = {}): Promise<RunResult> {
  const result = await run(command, options);
  if (result.exitCode !== 0) {
    const lines: string[] = [`Command failed (exit ${result.exitCode}): ${command}`];
    if (result.stderr) lines.push(`stderr: ${result.stderr}`);
    if (result.stdout) lines.push(`stdout: ${result.stdout}`);
    throw new Error(lines.join('\n'));
  }
  return result;
}

/** Formats a RunResult as a human-readable block for MCP output. */
export function formatResult(label: string, result: RunResult): string {
  const lines: string[] = [`${label} (exit ${result.exitCode})`];
  if (result.stdout) lines.push(result.stdout);
  if (result.stderr) lines.push(`[stderr] ${result.stderr}`);
  return lines.join('\n');
}

#!/usr/bin/env node
import { Command } from 'commander';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';

import { config, serverDir } from './config.js';
import { resolveToken } from './azuredevops.js';
import { TOOLS, findTool, type ToolDeps } from './tools/registry.js';

async function serve(): Promise<void> {
  const adoToken = resolveToken(config.azureDevOps.apiKeyFile, serverDir);

  process.stderr.write(
    `codemanagermcp: serving stdio MCP\n` +
    `  repositoryPath:  ${config.repositoryPath}\n` +
    `  mainBranch:      ${config.mainBranch}\n` +
    `  branchPrefix:    ${config.branchPrefix}\n` +
    `  repositories:    ${Object.keys(config.azureDevOps.repositories).join(', ')}\n` +
    `  deployPipeline:  #${config.azureDevOps.pipelines.deployPipelineId}\n` +
    `  ciPipeline:      #${config.azureDevOps.pipelines.ciPipelineId}\n` +
    (config.azureDevOps.pipelines.deletePipelineId
      ? `  deletePipeline:  #${config.azureDevOps.pipelines.deletePipelineId}\n`
      : `  deletePipeline:  (none configured)\n`) +
    `  ciTimeout:       ${config.azureDevOps.pipelines.ciTimeoutMinutes ?? 15} min\n` +
    `  token:           ${adoToken ? 'resolved' : 'MISSING'}\n` +
    `  serverDir:       ${serverDir}\n`,
  );

  const deps: ToolDeps = { config, serverDir, adoToken };

  const mcp = new McpServer({ name: 'codemanagermcp', version: '0.1.0' });

  for (const tool of TOOLS) {
    mcp.registerTool(
      tool.name,
      {
        description: tool.description,
        inputSchema: tool.inputShape,
      },
      async (input: unknown) => {
        try {
          const text = await tool.handler(input as never, deps);
          return { content: [{ type: 'text' as const, text }] };
        } catch (err) {
          return {
            content: [{ type: 'text' as const, text: `${tool.name} failed: ${(err as Error).message}` }],
            isError: true,
          };
        }
      },
    );
  }

  const transport = new StdioServerTransport();
  await mcp.connect(transport);

  const shutdown = async (): Promise<void> => { process.exit(0); };
  process.on('SIGINT',  () => { void shutdown(); });
  process.on('SIGTERM', () => { void shutdown(); });
}

async function probe(toolName: string, argsJson: string | undefined): Promise<void> {
  const adoToken = resolveToken(config.azureDevOps.apiKeyFile, serverDir);
  const deps: ToolDeps = { config, serverDir, adoToken };

  const tool = findTool(toolName);
  if (!tool) {
    process.stderr.write(`unknown tool: ${toolName}\n`);
    process.stderr.write(`available tools: ${TOOLS.map((t) => t.name).join(', ')}\n`);
    process.exit(2);
  }

  let parsedArgs: unknown = {};
  if (argsJson !== undefined && argsJson.length > 0) {
    try {
      parsedArgs = JSON.parse(argsJson);
    } catch (err) {
      throw new Error(`Invalid JSON for tool args: ${(err as Error).message}`);
    }
  }

  const text = await tool.handler(parsedArgs as never, deps);
  process.stdout.write(text + '\n');
}

async function listToolsCommand(): Promise<void> {
  for (const t of TOOLS) {
    process.stdout.write(`${t.name}\n  ${t.description}\n`);
    for (const [name, schema] of Object.entries(t.inputShape)) {
      const desc = schema.description ?? '';
      const optional = schema.isOptional() ? '' : ' (required)';
      process.stdout.write(`  - ${name}${optional}${desc ? ` — ${desc}` : ''}\n`);
    }
    process.stdout.write('\n');
  }
}

const program = new Command();

program
  .name('codemanagermcp')
  .description(
    'MCP server that orchestrates workflow verbs ' +
    '(start_feature, push_changes, accept_changes, abandon_changes) ' +
    'backed by Azure DevOps Repos and Pipelines.',
  );

program
  .command('serve', { isDefault: true })
  .description('Start the stdio MCP server (default).')
  .action(async () => { await serve(); });

program
  .command('probe <tool> [argsJson]')
  .description('Invoke a single tool from the command line without an MCP client. One-shot, for debugging.')
  .action(async (toolName: string, argsJson?: string) => {
    await probe(toolName, argsJson);
  });

program
  .command('tools')
  .description('List available tools and their input schemas.')
  .action(async () => { await listToolsCommand(); });

program.parseAsync(process.argv).catch((err: unknown) => {
  const e   = err as { message?: string; code?: string };
  const msg = e?.message ?? e?.code ?? (typeof err === 'string' ? err : '') ?? 'unknown error';
  process.stderr.write(`codemanagermcp: ${msg}\n`);
  process.exit(1);
});

export interface WorkflowState {
  /** Human-readable feature name as passed to start_feature. */
  featureName: string;
  /** Full branch name (branchPrefix + slugified featureName). */
  branchName: string;
  /** Slugified feature name (used as BRANCH_SLUG pipeline variable). */
  branchSlug: string;
  /** Whether the ephemeral environment has been deployed at least once. */
  envDeployed: boolean;
  /** ADO run ID of the most recent deploy pipeline run, for status polling. */
  lastDeployRunId?: number;
  /** ADO run ID of the most recent CI pipeline run, for status polling. */
  lastCiRunId?: number;
  /** Azure DevOps PR ID, set after accept_changes creates or finds the PR. */
  prId?: number;
  /** Azure DevOps PR web URL. */
  prUrl?: string;
}

function statePath(dataDirPath: string): string {
  return resolve(dataDirPath, 'state.json');
}

function ensureDir(dir: string): void {
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

/** Reads the current workflow state, or null if none exists. */
export function readState(dataDirPath: string): WorkflowState | null {
  const path = statePath(dataDirPath);
  if (!existsSync(path)) return null;
  try {
    const raw = readFileSync(path, 'utf-8').trim();
    if (!raw || raw === '{}') return null;
    return JSON.parse(raw) as WorkflowState;
  } catch {
    return null;
  }
}

/** Persists workflow state to disk. */
export function writeState(dataDirPath: string, state: WorkflowState): void {
  ensureDir(dataDirPath);
  writeFileSync(statePath(dataDirPath), JSON.stringify(state, null, 2), 'utf-8');
}

/** Merges a partial update into the current state and persists it. */
export function patchState(dataDirPath: string, patch: Partial<WorkflowState>): WorkflowState {
  const current = readState(dataDirPath);
  if (!current) throw new Error('codemanagermcp: no active feature — call start_feature first.');
  const next: WorkflowState = { ...current, ...patch };
  writeState(dataDirPath, next);
  return next;
}

/** Removes the state file, signalling no active feature. */
export function clearState(dataDirPath: string): void {
  const path = statePath(dataDirPath);
  if (existsSync(path)) rmSync(path);
}

/** Returns the data directory path used by this config directory. */
export function dataDir(configDir: string): string {
  return resolve(configDir, 'data');
}

import { z } from 'zod';
import { run } from '../runner.js';
import { readState, clearState, dataDir } from '../state.js';
import { resolveRepository, slugify } from '../config.js';
import { queuePipelineRun } from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const abandonChangesShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
  force: z
    .boolean()
    .optional()
    .default(false)
    .describe(
      'Skip the safety guard that prevents abandoning when a PR already exists. Default: false.',
    ),
  reason: z
    .string()
    .optional()
    .describe('Optional reason for the audit log.'),
};

export interface AbandonChangesInput {
  repository: string;
  force?: boolean;
  reason?: string;
}

export async function abandonChanges(
  input: AbandonChangesInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig = resolveRepository(input.repository);
  const state     = readState(dataDir(serverDir));
  if (!state) {
    return 'No active feature to abandon. State is already clear.';
  }

  const { branchName, branchSlug, featureName, prUrl, envDeployed } = state;
  const slug  = branchSlug ?? slugify(featureName);
  const force = input.force ?? false;
  const repo  = config.repositoryPath;
  const lines: string[] = [];

  lines.push(`feature: ${featureName}`);
  lines.push(`branch:  ${branchName}`);
  lines.push(`target:  ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  if (input.reason) lines.push(`reason:  ${input.reason}`);
  lines.push('');

  // ── Safety guard ──────────────────────────────────────────────────────────
  if (prUrl && !force) {
    lines.push(
      `SAFETY: an open PR exists at ${prUrl}.\n` +
      `Pass force=true to abandon anyway. The PR will remain open in Azure DevOps — abandon it there manually.`,
    );
    return lines.join('\n');
  }

  // ── Tear down deploy environment ──────────────────────────────────────────
  const deletePipelineId = config.azureDevOps.pipelines.deletePipelineId;

  if (envDeployed && deletePipelineId) {
    lines.push(`[pipeline] queue delete-env pipeline #${deletePipelineId}`);
    try {
      const delRun = await queuePipelineRun(
        adoConfig, adoToken, deletePipelineId,
        { branchName, branchSlug: slug, featureName },
      );
      lines.push(`[pipeline] teardown queued: ${delRun.webUrl}`);
    } catch (err) {
      lines.push(`[warn] teardown pipeline failed to queue: ${(err as Error).message}. Continuing cleanup.`);
    }
  } else if (envDeployed && !deletePipelineId) {
    lines.push('[env] no deletePipelineId configured — skipping environment teardown.');
  } else {
    lines.push('[env] environment was not deployed — nothing to tear down.');
  }

  // ── Return to main branch ─────────────────────────────────────────────────
  lines.push(`[git] checkout ${config.mainBranch}`);
  const checkoutResult = await run(`git -C "${repo}" checkout ${config.mainBranch}`);
  if (checkoutResult.exitCode !== 0) {
    lines.push(`[warn] checkout failed: ${checkoutResult.stderr}`);
  }

  // ── Delete local branch ───────────────────────────────────────────────────
  lines.push(`[git] branch -D ${branchName}`);
  const localDelete = await run(`git -C "${repo}" branch -D ${branchName}`);
  if (localDelete.exitCode !== 0) {
    lines.push(`[warn] local delete: ${localDelete.stderr || localDelete.stdout}`);
  }

  // ── Delete remote branch (best-effort; ADO also auto-deletes on PR close) ─
  lines.push(`[git] push origin --delete ${branchName}`);
  const remoteDelete = await run(`git -C "${repo}" push origin --delete ${branchName}`);
  if (remoteDelete.exitCode !== 0) {
    lines.push(
      `[warn] remote branch delete exited ${remoteDelete.exitCode}: ` +
      `${remoteDelete.stderr || remoteDelete.stdout}`,
    );
  }

  // ── Clear state ───────────────────────────────────────────────────────────
  clearState(dataDir(serverDir));

  lines.push('');
  lines.push(`✓ Feature "${featureName}" abandoned. Branch and environment cleaned up.`);
  lines.push('  Call start_feature to begin a new feature.');

  return lines.join('\n');
}

import { z } from 'zod';
import { run } from '../runner.js';
import { readState, patchState, dataDir } from '../state.js';
import { resolveRepository, slugify } from '../config.js';
import {
  createPullRequest,
  queuePipelineRun,
  waitForPipelineRun,
} from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const acceptChangesShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
  title: z
    .string()
    .optional()
    .describe('PR title. Defaults to "feat: {branchSlug}" when omitted.'),
  description: z
    .string()
    .optional()
    .describe('PR description. Defaults to a brief generated summary.'),
};

export interface AcceptChangesInput {
  repository: string;
  title?: string;
  description?: string;
}

export async function acceptChanges(
  input: AcceptChangesInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig = resolveRepository(input.repository);
  const state     = readState(dataDir(serverDir));
  if (!state) {
    throw new Error('No active feature. Call start_feature first.');
  }

  const { branchName, branchSlug, featureName } = state;
  const slug = branchSlug ?? slugify(featureName);
  const repo = config.repositoryPath;
  const lines: string[] = [];

  lines.push(`feature: ${featureName}`);
  lines.push(`branch:  ${branchName} → ${config.mainBranch}`);
  lines.push(`target:  ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  lines.push('');

  // ── Ensure latest is pushed ───────────────────────────────────────────────
  lines.push(`[git] push -u origin ${branchName}`);
  const pushResult = await run(`git -C "${repo}" push -u origin ${branchName}`);
  if (pushResult.exitCode !== 0 && !pushResult.stderr.includes('Everything up-to-date')) {
    lines.push(`[warn] push: ${pushResult.stderr || pushResult.stdout}`);
  }

  // ── Tear down deploy environment (fire-and-forget) ────────────────────────
  const deletePipelineId = config.azureDevOps.pipelines.deletePipelineId;
  if (deletePipelineId && state.envDeployed) {
    lines.push(`[pipeline] queue delete-env pipeline #${deletePipelineId}`);
    try {
      const delRun = await queuePipelineRun(
        adoConfig, adoToken, deletePipelineId,
        { branchName, branchSlug: slug, featureName },
      );
      lines.push(`[pipeline] teardown queued: ${delRun.webUrl}`);
      patchState(dataDir(serverDir), { envDeployed: false });
    } catch (err) {
      lines.push(`[warn] teardown pipeline failed to queue: ${(err as Error).message}`);
    }
  }

  // ── Create Pull Request ───────────────────────────────────────────────────
  lines.push('');
  const prTitle = input.title ?? `feat: ${slug}`;
  const prDescription =
    input.description ??
    `Automated PR for feature **${featureName}**.\n\nBranch: \`${branchName}\``;

  try {
    const pr = await createPullRequest(
      adoConfig,
      adoToken,
      {
        title: prTitle,
        description: prDescription,
        sourceBranch: branchName,
        targetBranch: config.mainBranch,
      },
    );

    patchState(dataDir(serverDir), { prId: pr.prId, prUrl: pr.url });

    lines.push(
      pr.alreadyExists
        ? `[pr] existing PR #${pr.prId}: ${pr.url}`
        : `[pr] created PR #${pr.prId}: ${pr.url}`,
    );
  } catch (err) {
    lines.push(`[pr] WARN: could not create PR — ${(err as Error).message}`);
  }

  // ── Queue CI pipeline and wait ────────────────────────────────────────────
  lines.push('');
  const ciPipelineId = config.azureDevOps.pipelines.ciPipelineId;
  const timeoutMs    = (config.azureDevOps.pipelines.ciTimeoutMinutes ?? 15) * 60 * 1_000;

  lines.push(`[pipeline] queue CI pipeline #${ciPipelineId}`);
  const ciRun = await queuePipelineRun(
    adoConfig, adoToken, ciPipelineId,
    { branchName, branchSlug: slug, featureName },
  );
  lines.push(`[pipeline] CI run #${ciRun.id} started — ${ciRun.webUrl}`);
  patchState(dataDir(serverDir), { lastCiRunId: ciRun.id });

  lines.push(`[pipeline] waiting for CI (timeout: ${config.azureDevOps.pipelines.ciTimeoutMinutes ?? 15} min)…`);
  const finalRun = await waitForPipelineRun(
    adoConfig, adoToken, ciPipelineId, ciRun.id,
    15_000,
    timeoutMs,
  );

  // ── Evaluate CI result ────────────────────────────────────────────────────
  lines.push('');

  if (finalRun.state !== 'completed') {
    lines.push(`CI pipeline still running after timeout: ${finalRun.webUrl}`);
    lines.push('Call get_status to check current pipeline state, or open the URL above.');
    return lines.join('\n');
  }

  if (finalRun.result !== 'succeeded') {
    lines.push(`CI FAILED (result: ${finalRun.result})`);
    lines.push(`Pipeline run: ${finalRun.webUrl}`);
    lines.push('');
    lines.push(
      'Action required: open the pipeline URL above to read the failure details. ' +
      'Fix the failing tests or build errors, then call push_changes and accept_changes again.',
    );
    return lines.join('\n');
  }

  // ── All green ─────────────────────────────────────────────────────────────
  lines.push('✓ CI pipeline succeeded.');

  const latestState = readState(dataDir(serverDir));
  if (latestState?.prUrl) {
    lines.push(`✓ PR ready for review: ${latestState.prUrl}`);
  }

  lines.push(
    '  Next: the PR is now ready for the downstream security review gate. ' +
    'Call abandon_changes only if the feature is being scrapped.',
  );

  return lines.join('\n');
}

import { z } from 'zod';
import { run } from '../runner.js';
import { readState, dataDir } from '../state.js';
import { resolveRepository } from '../config.js';
import { getPipelineRun } from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const getStatusShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
};

export interface GetStatusInput {
  repository: string;
}

export async function getStatus(
  input: GetStatusInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig = resolveRepository(input.repository);
  const state     = readState(dataDir(serverDir));
  const repo      = config.repositoryPath;
  const lines: string[] = [];

  // ── Workflow state ────────────────────────────────────────────────────────
  if (state) {
    lines.push(`feature:     ${state.featureName}`);
    lines.push(`branch:      ${state.branchName}`);
    lines.push(`slug:        ${state.branchSlug}`);
    lines.push(`env:         ${state.envDeployed ? 'deployed' : 'not deployed'}`);
    if (state.prUrl) lines.push(`pr:          ${state.prUrl}`);
  } else {
    lines.push('workflow:    no active feature');
  }

  lines.push(`target:      ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  lines.push('');

  // ── Git working tree ──────────────────────────────────────────────────────
  const currentBranch = await run(`git -C "${repo}" branch --show-current`);
  lines.push(`git branch:  ${currentBranch.stdout || '(detached HEAD)'}`);

  const gitStatus = await run(`git -C "${repo}" status --short`);
  if (gitStatus.stdout) {
    lines.push(`git status:\n${gitStatus.stdout}`);
  } else {
    lines.push('git status:  clean');
  }

  const lastCommit = await run(
    `git -C "${repo}" log -1 --pretty=format:"%h %s (%cr)" HEAD`,
  );
  if (lastCommit.stdout) {
    lines.push(`last commit: ${lastCommit.stdout}`);
  }

  if (!state) return lines.join('\n');

  // ── Pipeline run status ───────────────────────────────────────────────────
  lines.push('');

  if (state.lastDeployRunId) {
    lines.push(`[deploy pipeline]`);
    try {
      const deployRun = await getPipelineRun(
        adoConfig, adoToken,
        config.azureDevOps.pipelines.deployPipelineId,
        state.lastDeployRunId,
      );
      lines.push(`  run #${deployRun.id}  state: ${deployRun.state}  result: ${deployRun.result}`);
      lines.push(`  ${deployRun.webUrl}`);
    } catch (err) {
      lines.push(`  could not query deploy run: ${(err as Error).message}`);
    }
  }

  if (state.lastCiRunId) {
    lines.push(`[CI pipeline]`);
    try {
      const ciRun = await getPipelineRun(
        adoConfig, adoToken,
        config.azureDevOps.pipelines.ciPipelineId,
        state.lastCiRunId,
      );
      lines.push(`  run #${ciRun.id}  state: ${ciRun.state}  result: ${ciRun.result}`);
      lines.push(`  ${ciRun.webUrl}`);
    } catch (err) {
      lines.push(`  could not query CI run: ${(err as Error).message}`);
    }
  }

  return lines.join('\n');
}

import { z } from 'zod';
import { run, mustRun } from '../runner.js';
import { readState, patchState, dataDir } from '../state.js';
import { resolveRepository, slugify } from '../config.js';
import { queuePipelineRun } from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const pushChangesShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
  message: z
    .string()
    .optional()
    .describe('Commit message. Defaults to "wip: {branchSlug}" when omitted.'),
  stageAll: z
    .boolean()
    .optional()
    .default(true)
    .describe('Stage all changes (git add -A) before committing. Default: true.'),
};

export interface PushChangesInput {
  repository: string;
  message?: string;
  stageAll?: boolean;
}

export async function pushChanges(
  input: PushChangesInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig = resolveRepository(input.repository);
  const state     = readState(dataDir(serverDir));
  if (!state) {
    throw new Error('No active feature. Call start_feature first.');
  }

  const { branchName, branchSlug, featureName } = state;
  const repo  = config.repositoryPath;
  const lines: string[] = [];

  lines.push(`feature: ${featureName}`);
  lines.push(`branch:  ${branchName}`);
  lines.push(`target:  ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  lines.push('');

  // ── Ensure we are on the right branch ────────────────────────────────────
  const currentBranch = await run(`git -C "${repo}" branch --show-current`);
  if (currentBranch.stdout !== branchName) {
    lines.push(`[warn] current branch "${currentBranch.stdout}" ≠ "${branchName}". Switching.`);
    await mustRun(`git -C "${repo}" checkout ${branchName}`);
  }

  // ── Stage ─────────────────────────────────────────────────────────────────
  const stageAll = input.stageAll ?? true;
  if (stageAll) {
    lines.push('[git] add -A');
    await mustRun(`git -C "${repo}" add -A`);
  }

  // ── Commit if there is anything staged ───────────────────────────────────
  const statusResult  = await run(`git -C "${repo}" status --porcelain`);
  const hasChanges    = statusResult.stdout.length > 0;

  if (hasChanges) {
    const message = input.message ?? `wip: ${branchSlug}`;
    lines.push(`[git] commit -m "${message}"`);
    await mustRun(`git -C "${repo}" commit -m "${message.replace(/"/g, '\\"')}"`);
  } else {
    lines.push('[git] nothing to commit — skipping commit step');
  }

  // ── Push ──────────────────────────────────────────────────────────────────
  lines.push(`[git] push -u origin ${branchName}`);
  const pushResult = await mustRun(`git -C "${repo}" push -u origin ${branchName}`);
  if (pushResult.stderr) lines.push(pushResult.stderr);

  // ── Trigger deploy pipeline ───────────────────────────────────────────────
  const pipelineId = config.azureDevOps.pipelines.deployPipelineId;
  lines.push(`[pipeline] queue deploy pipeline #${pipelineId}`);

  const run2 = await queuePipelineRun(
    adoConfig,
    adoToken,
    pipelineId,
    { branchName, branchSlug: branchSlug ?? slugify(featureName), featureName },
  );

  lines.push(`[pipeline] queued run #${run2.id} — ${run2.webUrl}`);

  patchState(dataDir(serverDir), { envDeployed: true, lastDeployRunId: run2.id });

  lines.push('');
  lines.push(
    hasChanges
      ? `✓ Changes committed and pushed to "${branchName}". Deploy pipeline queued.`
      : `✓ Pushed (no new commit). Deploy pipeline queued.`,
  );
  lines.push(`  Deploy: ${run2.webUrl}`);
  lines.push(`  Next: call accept_changes to open a PR and run CI, or push more changes.`);

  return lines.join('\n');
}

import type { z } from 'zod';
import type { CodeManagerConfig } from '../config.js';
import { startFeature, startFeatureShape, type StartFeatureInput } from './start_feature.js';
import { pushChanges,  pushChangesShape,  type PushChangesInput  } from './push_changes.js';
import { acceptChanges, acceptChangesShape, type AcceptChangesInput } from './accept_changes.js';
import { abandonChanges, abandonChangesShape, type AbandonChangesInput } from './abandon_changes.js';
import { getStatus, getStatusShape, type GetStatusInput } from './get_status.js';

export interface ToolDeps {
  config: CodeManagerConfig;
  /** Directory holding the running server.js — used for state/data and PAT file resolution. */
  serverDir: string;
  /** Resolved Azure DevOps PAT — read once at server startup. */
  adoToken: string;
}

/**
 * Tool registration record. `inputShape` is a Zod raw shape passed to
 * `McpServer.registerTool` — the SDK wraps it into an object schema and uses it
 * for both JSON Schema generation (for the LLM) and runtime input validation.
 * Handlers receive the validated input directly.
 */
export interface ToolDef {
  name: string;
  description: string;
  inputShape: Record<string, z.ZodTypeAny>;
  handler: (input: never, deps: ToolDeps) => Promise<string>;
}

export function findTool(name: string): ToolDef | undefined {
  return TOOLS.find((t) => t.name === name);
}

import { z } from 'zod';
import { mustRun } from '../runner.js';
import { writeState, dataDir } from '../state.js';
import { featureBranch, resolveRepository, slugify } from '../config.js';
import { queuePipelineRun } from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const startFeatureShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
  name: z
    .string()
    .min(1)
    .describe(
      'Short human-readable feature name (e.g. "add user auth"). ' +
      'Automatically slugified into a safe branch name.',
    ),
};

export interface StartFeatureInput {
  repository: string;
  name: string;
}

export async function startFeature(
  input: StartFeatureInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig   = resolveRepository(input.repository);
  const featureName = input.name;
  const branchSlug  = slugify(featureName);

  if (!branchSlug) {
    throw new Error(`"${featureName}" produces an empty slug — use alphanumeric characters.`);
  }

  const branchName = featureBranch(branchSlug);
  const repo       = config.repositoryPath;
  const lines: string[] = [];

  lines.push(`feature: ${featureName}`);
  lines.push(`branch:  ${branchName}`);
  lines.push(`slug:    ${branchSlug}`);
  lines.push(`target:  ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  lines.push('');

  // ── Git: sync main and create branch ─────────────────────────────────────
  lines.push(`[git] checkout ${config.mainBranch}`);
  await mustRun(`git -C "${repo}" checkout ${config.mainBranch}`);

  lines.push(`[git] pull origin ${config.mainBranch}`);
  await mustRun(`git -C "${repo}" pull origin ${config.mainBranch}`);

  lines.push(`[git] checkout -b ${branchName}`);
  await mustRun(`git -C "${repo}" checkout -b ${branchName}`);

  // ── Push branch so Azure Pipelines can see it ─────────────────────────────
  lines.push(`[git] push -u origin ${branchName}`);
  await mustRun(`git -C "${repo}" push -u origin ${branchName}`);

  // ── Trigger deploy pipeline ───────────────────────────────────────────────
  const pipelineId = config.azureDevOps.pipelines.deployPipelineId;
  lines.push(`[pipeline] queue deploy pipeline #${pipelineId}`);

  const run = await queuePipelineRun(
    adoConfig,
    adoToken,
    pipelineId,
    { branchName, branchSlug, featureName },
  );

  lines.push(`[pipeline] queued run #${run.id} — ${run.webUrl}`);

  // ── Persist state ─────────────────────────────────────────────────────────
  writeState(dataDir(serverDir), {
    featureName,
    branchName,
    branchSlug,
    envDeployed: true,
    lastDeployRunId: run.id,
  });

  lines.push('');
  lines.push(`✓ Feature started.`);
  lines.push(`  Branch "${branchName}" created and pushed.`);
  lines.push(`  Deploy pipeline running: ${run.webUrl}`);
  lines.push(`  Next: make changes, then call push_changes to commit and redeploy.`);

  return lines.join('\n');
}

